script/AddEthNativeV4Adapters.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {IAdapterFees} from "contracts/interfaces/IAdapterFees.sol";
import {PoolKey} from "contracts/adapters/uniswap/v4/IPoolManagerMinimal.sol";
import {IPositionManagerMinimal} from "contracts/adapters/uniswap/v4/IPositionManagerMinimal.sol";
import {INativeWrapperMinimal} from "contracts/adapters/uniswap/IWETH9Minimal.sol";
import {UniswapV4NativeEthAdapter} from "contracts/adapters/UniswapV4NativeEthAdapter.sol";
import {UniversalRouterNativeSwapExecutor} from "contracts/swap/UniversalRouterNativeSwapExecutor.sol";

/// @notice OPS (4663 mainnet): register COUNT (default 3) UniswapV4NativeEthAdapter on the REAL mainnet
///         native ETH/USDG FablesRampETH v4 pool — the exact mirror of the demo chain's "demo" (sunEthLP)
///         vault adapter set (script/DemoLocalFork.s.sol `_deployNatives`): poolKey {currency0 address(0),
///         USDG, 0x800000 dynamic fee, spacing 10, FablesRampETH 0x06a8…}, v3 fee-100 pool TWAP reference,
///         a fresh UniversalRouterNativeSwapExecutor, range ±600 ticks, TWAP window 1800 s, slippage 200 bps,
///         swap venue = V4_POOL. The PONS/USDG FablesRamp (hooked) variant cannot attach to the sunEthLP
///         vault — its token registry is [USDG, WETH] and PONS is not registered (PoolmigoVault__AdapterTokenNotRegistered).
///   forge script script/AddEthNativeV4Adapters.s.sol --rpc-url rhc --sender <owner> \
///     --account mysun-rehearsal --password-file <path> --broadcast
///   Env: COUNT (default 3), OWNER (default msg.sender); broadcasting account must be the vault owner.
contract AddEthNativeV4Adapters is Script {
    address internal constant VAULT = 0x6767257AAFfCE82f6ba4B6E96EDBa80e9e1112FC; // 4663 sunEthLP
    address internal constant USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168; // currency1
    address internal constant FABLES_RAMP_ETH = 0x06a889870C8f83640D6816319f72e2aA579b6080; // bits 0x2080
    address internal constant POSM = 0x58daec3116aae6D93017bAAea7749052E8a04fA7; // v4 PositionManager
    address internal constant POOL_FEE100 = 0x52e65B17fB6E5BA00Ed806f37Afcd2DaA50271Ca; // v3 USDG/WETH 0.01%
    address internal constant UNIVERSAL_ROUTER = 0x204FAca1764B154221e35c0d20aBb3c525710498; // UR 2.1.2
    uint24 internal constant ETH_V4_FEE = 0x800000; // DYNAMIC_FEE_FLAG — the hook resolves each swap's fee
    int24 internal constant ETH_V4_TICK_SPACING = 10;
    int24 internal constant ETH_RANGE = 600; // ±600 ticks around the TWAP, snapped outward to spacing 10
    uint32 internal constant TWAP_WINDOW = 1800;
    uint16 internal constant ETH_MAX_SLIPPAGE_BPS = 200;

    function run() external {
        MySunVaultUpgradeable vault = MySunVaultUpgradeable(VAULT);
        uint256 count = vm.envOr("COUNT", uint256(3));
        address owner = vm.envOr("OWNER", msg.sender);

        require(msg.sender == owner, "AddEthNativeV4Adapters: OWNER must be the broadcasting account");
        require(vault.owner() == owner, "AddEthNativeV4Adapters: not the vault owner");
        require(vault.adapterCount() + count <= vault.MAX_ADAPTERS(), "AddEthNativeV4Adapters: COUNT exceeds MAX_ADAPTERS");

        PoolKey memory key = PoolKey({
            currency0: address(0), // NATIVE ETH
            currency1: USDG,
            fee: ETH_V4_FEE,
            tickSpacing: ETH_V4_TICK_SPACING,
            hooks: FABLES_RAMP_ETH
        });

        IPositionManagerMinimal posm = IPositionManagerMinimal(POSM);
        console2.log("chainId              :", block.chainid);
        console2.log("vault                :", VAULT);
        console2.log("posm.permit2         :", address(posm.permit2()));
        console2.log("posm.WETH9           :", address(INativeWrapperMinimal(POSM).WETH9()));
        console2.log("vault.adapterCount   :", vault.adapterCount());
        console2.log("adding               :", count);

        vm.startBroadcast();
        address nativeExecutor = address(
            new UniversalRouterNativeSwapExecutor(
                UNIVERSAL_ROUTER, address(posm.permit2()), address(INativeWrapperMinimal(POSM).WETH9())
            )
        );
        console2.log("native executor      :", nativeExecutor);

        UniswapV4NativeEthAdapter[] memory added = new UniswapV4NativeEthAdapter[](count);
        for (uint256 i; i < count; ++i) {
            added[i] = new UniswapV4NativeEthAdapter(
                UniswapV4NativeEthAdapter.Config({
                    vault: VAULT,
                    positionManager: POSM,
                    poolKey: key,
                    refPool: POOL_FEE100,
                    swapRouter: UNIVERSAL_ROUTER,
                    swapExecutor: nativeExecutor,
                    owner: owner,
                    rangeTicksBelow: ETH_RANGE,
                    rangeTicksAbove: ETH_RANGE,
                    twapWindow: TWAP_WINDOW,
                    maxSlippageBps: ETH_MAX_SLIPPAGE_BPS
                })
            );
            added[i].setSwapVenue(UniswapV4NativeEthAdapter.SwapVenue.V4_POOL);
            vault.addAdapter(IPositionAdapter(address(added[i])));
            console2.log("added native adapter :", address(added[i]));
            console2.log("  vault.adapterCount :", vault.adapterCount());
        }
        vm.stopBroadcast();

        for (uint256 i; i < count; ++i) {
            UniswapV4NativeEthAdapter a = added[i];
            require(vault.isAdapter(address(a)), "AddEthNativeV4Adapters: NOT registered");
            require(a.owner() == owner, "AddEthNativeV4Adapters: owner mismatch");
            require(a.HOOKS() == FABLES_RAMP_ETH, "AddEthNativeV4Adapters: hook mismatch");
            require(a.poolId() == keccak256(abi.encode(key)), "AddEthNativeV4Adapters: poolId mismatch");
            require(a.supportsInterface(type(IAdapterFees).interfaceId), "AddEthNativeV4Adapters: missing IAdapterFees");
            console2.log("verify OK            :", address(a), "| tokenId:", a.tokenId());
        }
        console2.log("final vault.adapterCount:", vault.adapterCount());
    }
}

script/AddSamePoolV3Adapters.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {ISwapExecutor} from "contracts/interfaces/ISwapExecutor.sol";
import {UniswapV3Adapter} from "contracts/adapters/UniswapV3Adapter.sol";

/**
 * @notice OPS (4663 rehearsal vault): register COUNT more Uniswap v3 adapters on the SAME pool as an existing
 *         (mirror) v3 adapter of the vault — the interim to the deferred P5 multi-position work.
 *
 *         Each adapter owns exactly ONE live LP position (one range), so N adapters on one pool = N concurrent
 *         ranges there. Everything is mirrored from the existing adapter AT RUNTIME (the DemoAddRangeBand
 *         pattern): pool / NFPM / swap executor (+ its UniversalRouter and Permit2), owner, fresh-range offsets,
 *         TWAP window and max slippage. Range constraints are NOT set: the constructor default box (the widest
 *         legal box for the pool's tick spacing) is the mirror's box — verified and logged, never written.
 *         The keeper opens each position afterwards via `vault.addLiquidity(adapter, params)`.
 *
 *   cd contracts
 *   # simulate (nothing broadcast):
 *   forge script script/AddSamePoolV3Adapters.s.sol --rpc-url rhc --sender <vault owner>
 *   # broadcast:
 *   forge script script/AddSamePoolV3Adapters.s.sol --rpc-url rhc --sender <vault owner> \
 *     --account mysun-rehearsal --password-file <path> --broadcast
 *
 * Env: VAULT (vault proxy, default the 4663 rehearsal vault), MIRROR (existing v3 adapter to mirror, default its
 *      v3 adapter), COUNT (adapters to add, default 7 — this pool already has one → 8 total), OWNER (default the
 *      broadcasting account). The broadcasting
 *      account must be OWNER, the vault owner AND the mirror's owner — any mismatch reverts before broadcast.
 */
contract AddSamePoolV3Adapters is Script {
    address internal constant DEFAULT_VAULT = 0x6767257AAFfCE82f6ba4B6E96EDBa80e9e1112FC; // 4663 rehearsal sunEthLP
    address internal constant DEFAULT_MIRROR = 0x8962bcC3E13a6C038Fdb5B23f54Ff41F327fb51b; // its v3 adapter
    /// @dev This pool already has 1 adapter; +7 → 8 total (the owner's target).
    uint256 internal constant DEFAULT_COUNT = 7;

    function run() external returns (address[] memory added) {
        address vaultAddr = vm.envOr("VAULT", DEFAULT_VAULT);
        address mirrorAddr = vm.envOr("MIRROR", DEFAULT_MIRROR);
        uint256 count = vm.envOr("COUNT", DEFAULT_COUNT);
        address owner = vm.envOr("OWNER", msg.sender);

        MySunVaultUpgradeable vault = MySunVaultUpgradeable(vaultAddr);
        UniswapV3Adapter mirror = UniswapV3Adapter(mirrorAddr);
        require(msg.sender == owner, "AddSamePoolV3Adapters: OWNER must be the broadcasting account");
        require(vault.owner() == owner, "AddSamePoolV3Adapters: broadcasting account is not the vault owner");
        require(mirror.owner() == owner, "AddSamePoolV3Adapters: broadcasting account is not the mirror owner");
        require(mirror.VAULT() == vaultAddr, "AddSamePoolV3Adapters: MIRROR serves another vault");
        require(vault.isAdapter(mirrorAddr), "AddSamePoolV3Adapters: MIRROR is not registered on VAULT");
        require(count > 0, "AddSamePoolV3Adapters: COUNT is zero");
        require(
            vault.adapterCount() + count <= vault.MAX_ADAPTERS(), "AddSamePoolV3Adapters: COUNT exceeds MAX_ADAPTERS"
        );

        ISwapExecutor exec = mirror.SWAP_EXECUTOR();
        UniswapV3Adapter.Config memory cfg = UniswapV3Adapter.Config({
            vault: vaultAddr,
            pool: address(mirror.POOL()),
            positionManager: address(mirror.POSITION_MANAGER()),
            swapRouter: exec.UNIVERSAL_ROUTER(),
            permit2: exec.PERMIT2(),
            swapExecutor: address(exec),
            owner: mirror.owner(),
            rangeTicksBelow: mirror.rangeTicksBelow(),
            rangeTicksAbove: mirror.rangeTicksAbove(),
            twapWindow: mirror.twapWindow(),
            maxSlippageBps: mirror.maxSlippageBps()
        });

        console2.log("chainId              :", block.chainid);
        console2.log("vault                :", vaultAddr);
        console2.log("mirror               :", mirrorAddr);
        console2.log("vault.adapterCount   :", vault.adapterCount());
        console2.log("adding               :", count);

        added = new address[](count);
        vm.startBroadcast();
        for (uint256 i; i < count; ++i) {
            added[i] = address(new UniswapV3Adapter(cfg));
            vault.addAdapter(IPositionAdapter(added[i]));
            console2.log("added adapter        :", added[i]);
            console2.log("  vault.adapterCount :", vault.adapterCount());
        }
        vm.stopBroadcast();

        _logMirror(mirror, exec);
        for (uint256 i; i < count; ++i) {
            _verify(vault, mirror, UniswapV3Adapter(added[i]));
        }
        console2.log("final vault.adapterCount:", vault.adapterCount());
        console2.log("next (keeper): vault.addLiquidity(adapter, {range}) per new adapter");
    }

    function _logMirror(UniswapV3Adapter mirror, ISwapExecutor exec) internal view {
        (int24 minTick, int24 maxTick, int24 minRange, int24 maxRange) = mirror.rangeConstraints();
        console2.log("--- mirror (reference) ---");
        console2.log("pool                 :", address(mirror.POOL()));
        console2.log("positionManager      :", address(mirror.POSITION_MANAGER()));
        console2.log("swapExecutor         :", address(exec));
        console2.log("  UNIVERSAL_ROUTER   :", exec.UNIVERSAL_ROUTER());
        console2.log("  PERMIT2            :", exec.PERMIT2());
        console2.log("owner                :", mirror.owner());
        console2.log("rangeTicksBelow      :", int256(mirror.rangeTicksBelow()));
        console2.log("rangeTicksAbove      :", int256(mirror.rangeTicksAbove()));
        console2.log("twapWindow           :", uint256(mirror.twapWindow()));
        console2.log("maxSlippageBps       :", uint256(mirror.maxSlippageBps()));
        console2.log("rangeConstraints minTick      :", int256(minTick));
        console2.log("rangeConstraints maxTick      :", int256(maxTick));
        console2.log("rangeConstraints minRangeTicks:", int256(minRange));
        console2.log("rangeConstraints maxRangeTicks:", int256(maxRange));
    }

    /// @dev One verification row per new adapter; any mismatch vs the mirror reverts (fail loudly).
    function _verify(MySunVaultUpgradeable vault, UniswapV3Adapter mirror, UniswapV3Adapter a) internal view {
        bool venue = a.POOL() == mirror.POOL() && a.POSITION_MANAGER() == mirror.POSITION_MANAGER()
            && a.SWAP_EXECUTOR() == mirror.SWAP_EXECUTOR() && a.VAULT() == address(vault);
        bool owner = a.owner() == vault.owner() && a.owner() == mirror.owner();
        bool box = _sameBox(a, mirror);
        bool params = a.twapWindow() == mirror.twapWindow() && a.maxSlippageBps() == mirror.maxSlippageBps()
            && a.rangeTicksBelow() == mirror.rangeTicksBelow() && a.rangeTicksAbove() == mirror.rangeTicksAbove();
        bool registered = vault.isAdapter(address(a));
        uint8 caps = vault.adapterCapabilities(IPositionAdapter(address(a)));
        bool sameCaps = caps == vault.adapterCapabilities(IPositionAdapter(address(mirror)));

        console2.log("--- verify adapter ---", address(a));
        console2.log("  pool/nfpm/executor/vault == mirror:", venue);
        console2.log("  owner == vault owner == mirror owner:", owner);
        console2.log("  rangeConstraints == mirror:", box);
        console2.log("  twap/slippage/rangeTicks == mirror:", params);
        console2.log("  registered:", registered);
        console2.log("  capabilities (== mirror):", uint256(caps), sameCaps);
        console2.log("  tokenId (no live position):", a.tokenId());
        require(venue && owner && box && params && registered && sameCaps, "AddSamePoolV3Adapters: verify failed");
        require(a.tokenId() == 0, "AddSamePoolV3Adapters: unexpected live position");
    }

    function _sameBox(UniswapV3Adapter a, UniswapV3Adapter b) internal view returns (bool) {
        (int24 aMin, int24 aMax, int24 aMinR, int24 aMaxR) = a.rangeConstraints();
        (int24 bMin, int24 bMax, int24 bMinR, int24 bMaxR) = b.rangeConstraints();
        return aMin == bMin && aMax == bMax && aMinR == bMinR && aMaxR == bMaxR;
    }
}

script/DemoAddRangeBand.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {PoolmigoVaultUpgradeable} from "contracts/PoolmigoVaultUpgradeable.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {ISwapExecutor} from "contracts/interfaces/ISwapExecutor.sol";
import {UniswapV3Adapter} from "contracts/adapters/UniswapV3Adapter.sol";

/**
 * @notice DEMO-ONLY (the local RHC-fork stack): register a SECOND Uniswap v3 adapter on the SAME fee-100
 *         USDG/WETH pool as the demo vault's existing v3 adapter.
 *
 *         Each adapter owns exactly ONE live LP position (one range) — this is how the vault holds two
 *         different ranges in ONE pool: two adapters on that pool. This script deploys the extra adapter
 *         (venue wiring mirrored from the existing one: same pool / NFPM / router / executor) and the
 *         vault owner registers it. The keeper then opens the second position at a different range via
 *         `vault.addLiquidity(adapter2, params)`.
 *
 *   cd contracts
 *   forge script script/DemoAddRangeBand.s.sol --rpc-url http://127.0.0.1:8547 --broadcast \
 *     --private-key $DEPLOYER_KEY    # anvil #200 = the fork demo's OWNER — LOCAL ONLY (public test key;
 *                                    # cast wallet private-key --mnemonic "test … junk" --mnemonic-index 200)
 *
 * Env: VAULT (demo vault proxy), V3_ADAPTER (existing adapter to mirror), OWNER (default anvil #200 — the fork demo's deployer, script/fork-demo-up.sh).
 */
contract DemoAddRangeBand is Script {
    address internal constant DEFAULT_VAULT = 0x63763137C765BE274f1953e3C2e41E5668459977; // demo vault proxy
    address internal constant DEFAULT_V3_ADAPTER = 0x3369DA4782B69E8abD04bCDCAe761215825BD0E6; // existing v3 adapter
    address internal constant DEFAULT_OWNER = 0xCD5691EA878D262516be278cb46f2fd7fF132083; // anvil #200

    int24 internal constant RANGE_BELOW = 300;
    int24 internal constant RANGE_ABOVE = 300;
    uint32 internal constant TWAP_WINDOW = 1800;
    uint16 internal constant MAX_SLIPPAGE_BPS = 100;

    function run() external returns (address adapter2) {
        address vault = vm.envOr("VAULT", DEFAULT_VAULT);
        address existing = vm.envOr("V3_ADAPTER", DEFAULT_V3_ADAPTER);
        address owner = vm.envOr("OWNER", DEFAULT_OWNER);
        require(msg.sender == owner, "DemoAddRangeBand: OWNER must be the broadcasting account");

        UniswapV3Adapter a1 = UniswapV3Adapter(existing);
        ISwapExecutor exec = a1.SWAP_EXECUTOR();

        vm.startBroadcast();
        adapter2 = address(
            new UniswapV3Adapter(
                UniswapV3Adapter.Config({
                    vault: vault,
                    pool: address(a1.POOL()),
                    positionManager: address(a1.POSITION_MANAGER()),
                    swapRouter: exec.UNIVERSAL_ROUTER(),
                    permit2: exec.PERMIT2(),
                    swapExecutor: address(exec),
                    owner: owner,
                    rangeTicksBelow: RANGE_BELOW,
                    rangeTicksAbove: RANGE_ABOVE,
                    twapWindow: TWAP_WINDOW,
                    maxSlippageBps: MAX_SLIPPAGE_BPS
                })
            )
        );
        PoolmigoVaultUpgradeable(vault).addAdapter(IPositionAdapter(adapter2));
        vm.stopBroadcast();

        console2.log("adapter2 (same pool) :", adapter2);
        console2.log("pool                 :", address(a1.POOL()));
        console2.log("vault.adapterCount   :", PoolmigoVaultUpgradeable(vault).adapterCount());
        console2.log("existing tokenId     :", a1.tokenId());
        console2.log("existing tickLower   :", int256(a1.tickLower()));
        console2.log("existing tickUpper   :", int256(a1.tickUpper()));
        console2.log("next (keeper): vault.addLiquidity(adapter2, {different range});");
    }
}

script/DemoLocal.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {DepositSplit} from "contracts/periphery/DepositSplit.sol";
import {MockPositionAdapter} from "test/mocks/MockPositionAdapter.sol";
import {MockToken} from "test/mocks/MockToken.sol";

/**
 * @notice One-shot local demo stack for Anvil — the shared dev chain for frontend/backend work.
 *
 * Deploys TWO vaults on one chain (per-vault receipt naming — notes/NAMING.md):
 *   - "demo"   — mUSDG/mWETH basket, receipt `sunEthLP`, TWO mock position adapters (stand-ins for
 *                Uniswap V3 + V4 pools). Deploy order and values are unchanged from the one-vault
 *                stack, so on a fresh anvil its addresses are the same as before.
 *   - "stocks" — mUSDG + 5 mock stock tokens (mNVDA, mAAPL, mTSLA, mSPY, mGME), receipt
 *                `sun5StocksLP`, one mock adapter per mUSDG/stock pair. Its proxy reuses the demo
 *                vault's (already OZ-validated) implementation.
 * For each vault: the owner-only genesis deposit (mints K), the keeper deploys part of the capital
 * into adapters, harvestable fees are seeded. Writes `shared/deployment.local.json` in the v2
 * (multi-vault) schema — the single source of truth for addresses consumed by frontend/ and backend/.
 *
 * Usage (with anvil running):
 *   anvil --port 8547 --chain-id 46630
 *   forge clean && forge build          # OZ plugin requirement: fresh single build-info
 *   forge script script/DemoLocal.s.sol --rpc-url http://127.0.0.1:8547 --broadcast \
 *     --private-key $ANVIL_DEV_KEY      # anvil #0 — LOCAL ONLY public test key
 *
 * The dev keys/accounts below are the publicly known Anvil defaults. They are inert and must
 * NEVER be funded on a real network. Run against a FRESH anvil (re-running against a used chain
 * would deploy a second stack; that is harmless but confusing).
 */
contract DemoLocal is Script {
    /* ================ Anvil dev accounts (public, well-known — LOCAL ONLY) ================ */
    address internal constant OWNER = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266; // #0, deployer
    address internal constant KEEPER = 0x70997970C51812dc3A010C7d01b50e0d17dc79C8; // #1, keeper service
    address internal constant DEMO_USER = 0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC; // #2, frontend tester
    uint256 internal constant ANVIL_KEY_1 = 0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d; // #1 — LOCAL ONLY

    /// @dev RPC written into the JSON — the shared dev chain, regardless of which RPC this run used.
    string internal constant RPC_URL = "http://127.0.0.1:8547";
    uint16 internal constant FEE_BPS = 1000; // 10% performance fee (both vaults)

    /* ---------------- vault A: "demo" (mUSDG / mWETH) ---------------- */
    /// @dev Genesis K: demo stand-in for the team's one-time off-chain valuation of the seed basket.
    uint256 internal constant GENESIS_SHARES = 10_000e18;
    /// @dev Receipt-token supply cap (PRD F1.2), raised in stages by the owner. 0 would mean uncapped.
    uint256 internal constant MAX_TOTAL_SUPPLY = 500_000e18;

    /* ---------------- vault B: "stocks" (mUSDG + 5 stocks) ---------------- */
    uint256 internal constant STOCKS_GENESIS_SHARES = 25_000e18;
    uint256 internal constant STOCKS_MAX_TOTAL_SUPPLY = 1_000_000e18;
    uint256 internal constant N_STOCKS = 5;

    struct DemoVault {
        address vault;
        address depositSplit; // the implementation's DepositSplit (not written to deployment.local.json)
        address[] basket;
        MockPositionAdapter adapterV3;
        MockPositionAdapter adapterV4;
    }

    struct StocksVault {
        address vault;
        address[] basket; // [mUSDG, mNVDA, mAAPL, mTSLA, mSPY, mGME]
        MockPositionAdapter[] pairs; // pairs[i] = [mUSDG, stock i]
    }

    function run() external {
        /* ------------- phase 1: deploy stacks + genesis deposits (deployer = anvil #0) ------------- */
        vm.startBroadcast();
        MockToken usdg = new MockToken("Mock USDG", "mUSDG", 6);
        MockToken weth = new MockToken("Mock WETH", "mWETH", 18);
        DemoVault memory a = _deployDemoVault(usdg, weth);
        StocksVault memory b = _deployStocksVault(usdg, Upgrades.getImplementationAddress(a.vault));
        vm.stopBroadcast();

        /* ------- phase 2: keeper deploys capital into adapters + seeds fees (anvil #1) ------- */
        vm.startBroadcast(ANVIL_KEY_1);
        _keeperDemo(a);
        _keeperStocks(b);
        vm.stopBroadcast();

        /* ------------------------------ logs + shared/deployment.local.json ------------------------------ */
        console2.log("== MySun local demo stack (2 vaults) ==");
        console2.log("chainId          :", block.chainid);
        console2.log("owner            :", OWNER);
        console2.log("keeper           :", KEEPER);
        console2.log("demo user        :", DEMO_USER);
        console2.log("mUSDG            :", address(usdg));
        console2.log("mWETH            :", address(weth));
        _logDemo(a);
        _logStocks(b);

        string memory vaultsJson = string.concat(
            "[",
            _vaultJson("demo", "mUSDG / mWETH basket", a.vault),
            ",",
            _vaultJson("stocks", "Stock-pair basket (5 stocks + mUSDG)", b.vault),
            "]"
        );
        // Seed the root via serializeJson: serializeString would store a JSON *array* as an escaped
        // string (only object-shaped values are parsed), so `vaults` goes in as parsed JSON.
        string memory root = "deployment";
        vm.serializeJson(root, string.concat("{\"vaults\":", vaultsJson, "}"));
        vm.serializeUint(root, "version", 2);
        vm.serializeUint(root, "chainId", block.chainid);
        string memory json = vm.serializeString(root, "rpcUrl", RPC_URL);
        vm.writeJson(json, "../shared/deployment.local.json");
        console2.log("wrote ../shared/deployment.local.json (schema v2, 2 vaults)");
    }

    /* =============================== vault A: "demo" =============================== */

    function _deployDemoVault(MockToken usdg, MockToken weth) internal returns (DemoVault memory a) {
        a.basket = new address[](2);
        a.basket[0] = address(usdg);
        a.basket[1] = address(weth);

        // The stateless deposit splitter the implementation pins (immutable); shared by both vaults' proxies.
        a.depositSplit = address(new DepositSplit());
        Options memory opts;
        opts.constructorData = abi.encode(a.depositSplit);
        a.vault = Upgrades.deployUUPSProxy(
            "MySunVaultUpgradeable.sol",
            abi.encodeCall(
                MySunVaultUpgradeable(address(0)).initialize,
                (OWNER, "sunEthLP", "sunEthLP", a.basket, OWNER, FEE_BPS, GENESIS_SHARES, MAX_TOTAL_SUPPLY)
            ),
            opts
        );

        a.adapterV3 = new MockPositionAdapter(a.basket, a.vault, bytes32("uniswap-v3"), bytes32("mUSDG/mWETH 0.05%"));
        a.adapterV4 = new MockPositionAdapter(a.basket, a.vault, bytes32("uniswap-v4"), bytes32("mUSDG/mWETH 0.30%"));

        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(a.vault);
        vaultC.addAdapter(a.adapterV3);
        vaultC.addAdapter(a.adapterV4);
        vaultC.setKeeper(KEEPER, true);

        // Fund the demo actors generously.
        usdg.mint(OWNER, 1_000_000e6);
        weth.mint(OWNER, 500e18);
        usdg.mint(DEMO_USER, 250_000e6);
        weth.mint(DEMO_USER, 50e18);

        // Genesis deposit — owner-only (this broadcast is anvil #0 == OWNER); defines the basket and mints
        // exactly GENESIS_SHARES (K), independent of the amounts.
        usdg.approve(a.vault, type(uint256).max);
        weth.approve(a.vault, type(uint256).max);
        uint256[] memory boot = new uint256[](2);
        boot[0] = 100_000e6;
        boot[1] = 10e18;
        vaultC.deposit(a.basket, boot, GENESIS_SHARES, OWNER);
    }

    function _keeperDemo(DemoVault memory a) internal {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(a.vault);
        vaultC.deployTo(a.adapterV3, _pair(50_000e6, 5e18));
        vaultC.deployTo(a.adapterV4, _pair(25_000e6, 2.5e18));

        // Pretend both positions accrued trading fees (harvestable via rebalance()).
        a.adapterV3.simulateFees(_pair(250e6, 0.05e18));
        a.adapterV4.simulateFees(_pair(100e6, 0.02e18));
    }

    /* ============================== vault B: "stocks" ============================== */

    function _deployStocksVault(MockToken usdg, address implementation) internal returns (StocksVault memory b) {
        MockToken[N_STOCKS] memory stocks = [
            new MockToken("Mock NVDA", "mNVDA", 18),
            new MockToken("Mock AAPL", "mAAPL", 18),
            new MockToken("Mock TSLA", "mTSLA", 18),
            new MockToken("Mock SPY", "mSPY", 18),
            new MockToken("Mock GME", "mGME", 18)
        ];
        bytes32[N_STOCKS] memory poolIds = [
            bytes32("mNVDA/mUSDG 0.30%"),
            bytes32("mAAPL/mUSDG 0.30%"),
            bytes32("mTSLA/mUSDG 0.30%"),
            bytes32("mSPY/mUSDG 0.05%"),
            bytes32("mGME/mUSDG 1.00%")
        ];

        b.basket = new address[](1 + N_STOCKS);
        b.basket[0] = address(usdg);
        for (uint256 i; i < N_STOCKS; ++i) {
            b.basket[1 + i] = address(stocks[i]);
        }

        // Second proxy over the demo vault's implementation (validated by Upgrades.deployUUPSProxy above;
        // same bytecode, so no second implementation is deployed).
        b.vault = address(
            new ERC1967Proxy(
                implementation,
                abi.encodeCall(
                    MySunVaultUpgradeable(address(0)).initialize,
                    (
                        OWNER,
                        "sun5StocksLP",
                        "sun5StocksLP",
                        b.basket,
                        OWNER,
                        FEE_BPS,
                        STOCKS_GENESIS_SHARES,
                        STOCKS_MAX_TOTAL_SUPPLY
                    )
                )
            )
        );
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(b.vault);

        b.pairs = new MockPositionAdapter[](N_STOCKS);
        for (uint256 i; i < N_STOCKS; ++i) {
            address[] memory pairTokens = new address[](2);
            pairTokens[0] = address(usdg);
            pairTokens[1] = address(stocks[i]);
            b.pairs[i] = new MockPositionAdapter(pairTokens, b.vault, bytes32("uniswap-v3"), poolIds[i]);
            vaultC.addAdapter(b.pairs[i]);
        }
        vaultC.setKeeper(KEEPER, true);

        // Fund: owner seeds the stocks basket; demo user gets a spread of every stock.
        usdg.mint(OWNER, 50_000e6);
        usdg.mint(DEMO_USER, 100_000e6);
        usdg.approve(b.vault, type(uint256).max);
        for (uint256 i; i < N_STOCKS; ++i) {
            stocks[i].mint(OWNER, 100e18);
            stocks[i].mint(DEMO_USER, 50e18);
            stocks[i].approve(b.vault, type(uint256).max);
        }

        // Genesis deposit — owner-only; mints exactly STOCKS_GENESIS_SHARES (K).
        uint256[] memory boot = new uint256[](1 + N_STOCKS);
        boot[0] = 20_000e6;
        for (uint256 i; i < N_STOCKS; ++i) {
            boot[1 + i] = 10e18;
        }
        vaultC.deposit(b.basket, boot, STOCKS_GENESIS_SHARES, OWNER);
    }

    function _keeperStocks(StocksVault memory b) internal {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(b.vault);
        // Two of the five pairs get capital (NVDA, AAPL); the other three stay empty (idle-only legs).
        vaultC.deployTo(b.pairs[0], _pair(4_000e6, 4e18));
        vaultC.deployTo(b.pairs[1], _pair(3_000e6, 3e18));

        b.pairs[0].simulateFees(_pair(40e6, 0.04e18));
        b.pairs[1].simulateFees(_pair(30e6, 0.03e18));
    }

    /* ==================================== helpers ==================================== */

    function _pair(uint256 x, uint256 y) internal pure returns (uint256[] memory arr) {
        arr = new uint256[](2);
        arr[0] = x;
        arr[1] = y;
    }

    /// @dev One entry of the v2 `vaults` array; name/symbol are read back from the chain.
    function _vaultJson(string memory key, string memory label, address vault) internal returns (string memory) {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(vault);
        string memory receiptObj = string.concat("receipt_", key);
        vm.serializeString(receiptObj, "name", vaultC.name());
        string memory receipt = vm.serializeString(receiptObj, "symbol", vaultC.symbol());

        string memory obj = string.concat("vault_", key);
        vm.serializeString(obj, "key", key);
        vm.serializeString(obj, "label", label);
        vm.serializeString(obj, "receipt", receipt);
        vm.serializeAddress(obj, "vault", vault);
        vm.serializeAddress(obj, "implementation", Upgrades.getImplementationAddress(vault));
        vm.serializeAddress(obj, "keeper", KEEPER);
        return vm.serializeAddress(obj, "demoUser", DEMO_USER);
    }

    function _logVault(string memory title, address vault) internal view {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(vault);
        console2.log(title);
        console2.log("vault (proxy)    :", vault);
        console2.log("implementation   :", Upgrades.getImplementationAddress(vault));
        console2.log("name / symbol    :", vaultC.name(), vaultC.symbol());
        console2.log("genesis shares   :", vaultC.genesisShares());
        console2.log("totalSupply      :", vaultC.totalSupply());
        console2.log("maxTotalSupply   :", vaultC.maxTotalSupply());
        (address[] memory t, uint256[] memory amt) = vaultC.totalTokens();
        for (uint256 i; i < t.length; ++i) {
            console2.log("total", MockToken(t[i]).symbol(), amt[i]);
        }
    }

    function _logDemo(DemoVault memory a) internal view {
        _logVault("-- vault [demo] --", a.vault);
        console2.log("deposit splitter :", a.depositSplit);
        console2.log("adapter (v3 mock):", address(a.adapterV3));
        console2.log("adapter (v4 mock):", address(a.adapterV4));
    }

    function _logStocks(StocksVault memory b) internal view {
        _logVault("-- vault [stocks] --", b.vault);
        for (uint256 i; i < b.pairs.length; ++i) {
            console2.log("adapter (pair)   :", MockToken(b.basket[1 + i]).symbol(), address(b.pairs[i]));
        }
    }
}

script/DemoLocalFork.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {DepositSplit} from "contracts/periphery/DepositSplit.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {UniswapV3Adapter} from "contracts/adapters/UniswapV3Adapter.sol";
import {UniswapV4Adapter} from "contracts/adapters/UniswapV4Adapter.sol";
import {UniswapV4HookedAdapter} from "contracts/adapters/UniswapV4HookedAdapter.sol";
import {UniswapV4NativeEthAdapter} from "contracts/adapters/UniswapV4NativeEthAdapter.sol";
import {INativeWrapperMinimal} from "contracts/adapters/uniswap/IWETH9Minimal.sol";
import {IUniswapV3PoolMinimal} from "contracts/adapters/uniswap/IUniswapV3PoolMinimal.sol";
import {INonfungiblePositionManager} from "contracts/adapters/uniswap/INonfungiblePositionManager.sol";
import {PoolKey} from "contracts/adapters/uniswap/v4/IPoolManagerMinimal.sol";
import {IPositionManagerMinimal} from "contracts/adapters/uniswap/v4/IPositionManagerMinimal.sol";
import {IPermit2Minimal} from "contracts/adapters/uniswap/v4/IPermit2Minimal.sol";
import {MySunZapIn} from "contracts/periphery/MySunZapIn.sol";
import {MySunZapOut} from "contracts/periphery/MySunZapOut.sol";
import {PlanExecutor} from "contracts/periphery/PlanExecutor.sol";
import {IMySunVault} from "contracts/interfaces/IMySunVault.sol";
import {UniversalRouterSwapExecutor} from "contracts/swap/UniversalRouterSwapExecutor.sol";
import {UniversalRouterNativeSwapExecutor} from "contracts/swap/UniversalRouterNativeSwapExecutor.sol";
import {MockPositionAdapter} from "test/mocks/MockPositionAdapter.sol";
import {MockToken} from "test/mocks/MockToken.sol";

/**
 * @notice Local demo stack on an Anvil FORK of Robinhood Chain — the fork sibling of DemoLocal.s.sol.
 *
 * Deploys TWO real vaults (and, opt-in, the mock "stocks" vault of DemoLocal.s.sol):
 *   - "demo"   — basket [USDG, WETH] = the REAL RHC tokens, receipt `sunEthLP`, NINE real adapters: ONE
 *                UniswapV3Adapter (USDG/WETH fee-100 pool; range ±300, TWAP 1800 s, slippage 100 bps) + EIGHT identical
 *                UniswapV4NativeEthAdapters on the NATIVE ETH/USDG v4 pool behind the FablesRampETH hook (dynamic fee,
 *                spacing 10; TWAP reference = the same v3 fee-100 pool; swap venue = the native pool itself through a
 *                dedicated UniversalRouterNativeSwapExecutor — the WETH⇄ETH bridge; params mirror
 *                test/fork/FablesRampEthUsdg.fork.t.sol: range ±600, TWAP 1800 s, slippage 200 bps). The basket holds
 *                WETH, never native ETH. The keeper seeds all nine with equal slices, so a deposit fans out over all.
 *                The former hookless UniswapV4Adapter (fee 500 / spacing 10) is no longer deployed by default —
 *                `DEMO_DEPLOY_V4_HOOKLESS=true` brings it back (then ten adapters).
 *   - "pons"   — basket [USDG, PONS] = the REAL RHC tokens, receipt `sunPonsLP`, EIGHT identical REAL
 *                UniswapV4HookedAdapters on the PONS/USDG v4 pool behind the FablesRamp hook (dynamic fee, spacing 60;
 *                TWAP reference = the v3 PONS/USDG fee-10000 pool; swap venue = the hooked v4 pool itself, the deep
 *                venue). Params mirror test/fork/FablesRampPons.fork.t.sol: range ±600 ticks, TWAP window 1800 s,
 *                max slippage 200 bps. The keeper seeds all eight with equal slices.
 *   - "stocks" — OFF by default; `DEMO_DEPLOY_STOCKS=true` deploys it as before (mUSDG + 5 mock stocks, receipt
 *                `sun5StocksLP`, mock adapters) and adds it to the registry between "demo" and "pons".
 * Plus the zap periphery, both owned by OWNER and registered to the "demo" vault only: `MySunZapIn` (route USDG → WETH)
 * and `MySunZapOut` (route WETH → USDG), both TWAP-window 600 s / slippage 50 bps / deviation 50 bps on the same
 * fee-100 pool — and the strategy-layer `PlanExecutor` for the "demo" vault (owned by OWNER; a vault keeper itself,
 * KEEPER whitelisted on it).
 * Genesis (owner deposits real USDG/WETH in kind → K) → keeper `deployTo` into EVERY real adapter (real
 * swaps, real LP NFTs owned by the adapters — asserted below). Writes `shared/deployment.local.json` (v2)
 * with extra root fields: `"fork": true`, `"mintable": false` (DemoLocal.s.sol omits both: absent = not a
 * fork, MockToken.mint available) and `"periphery"` = the two zaps + the plan executor
 * (`zapIn` / `zapOut` / `planExecutor`).
 *
 * Prerequisites — `script/fork-demo-up.sh` does all of this, in order:
 *   1. anvil --fork-url https://rpc.mainnet.chain.robinhood.com --chain-id 46630 --host 0.0.0.0 --port 8547
 *   2. fund OWNER / DEMO_USER / TRADER with real USDG + WETH (impersonate the fee-100 pool, transfer) and real PONS
 *      (impersonate 0x…dEaD, transfer)
 *   3. cast rpc evm_increaseTime 1800 && cast rpc evm_mine   — the adapters' spot≈TWAP guard: on a frozen
 *      fork, one window forward makes the pool's 1800 s TWAP equal its spot (the fork suites' vm.warp)
 *   4. forge clean && forge build   (OZ plugin: fresh single build-info)
 *   5. forge script script/DemoLocalFork.s.sol --rpc-url http://127.0.0.1:8547 --broadcast \
 *        --private-key $DEPLOYER_KEY    # anvil #201 (= OWNER) — LOCAL ONLY public test key
 *
 * Deployer = anvil #201 of the public test mnemonic, NOT #0/#200: those keys are world-known and third parties
 * use them on RHC mainnet (nonces drifted: 0x6f3/0x6fc for #0, 89 for #200 at fork block 83309800), so every CREATE
 * address of the stack drifts with it. #201 has never sent a transaction on RHC (nonce 0), so the stack's
 * addresses only change when this script does. Both broadcast phases run `vm.startBroadcast(OWNER)`: forge
 * refuses to run unless the key it was given IS #201.
 *
 * The dev keys/accounts below are the publicly known Anvil defaults. LOCAL ONLY — the fork is a private
 * copy of the chain; nothing here is ever broadcast to Robinhood Chain.
 */
contract DemoLocalFork is Script {
    /* ================ Anvil dev accounts (public, well-known — LOCAL ONLY) ================ */
    address internal constant OWNER = 0x9B63F0Cef479924E5d2C4E22DBE31E6d0353B448; // #201, deployer (nonce-stable)
    address internal constant KEEPER = 0x70997970C51812dc3A010C7d01b50e0d17dc79C8; // #1, keeper service
    address internal constant DEMO_USER = 0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC; // #2, frontend tester
    uint256 internal constant ANVIL_KEY_1 = 0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d; // #1 — LOCAL ONLY

    /// @dev RPC written into the JSON — the shared dev chain, regardless of which RPC this run used.
    string internal constant RPC_URL = "http://127.0.0.1:8547";
    uint16 internal constant FEE_BPS = 1000; // 10% performance fee (both vaults)
    uint256 internal constant EXPECTED_CHAIN_ID = 46630; // the fork runs with the RHC testnet id

    /* ============ verified RHC addresses (notes/RHC_ADDRESSES.md — never invent one) ============ */
    address internal constant USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168; // 6 dp, v3/v4 token1
    address internal constant WETH = 0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73; // 18 dp, v3/v4 token0
    address internal constant POOL_FEE100 = 0x52e65B17fB6E5BA00Ed806f37Afcd2DaA50271Ca; // v3 USDG/WETH 0.01%
    address internal constant NFPM = 0x73991a25C818Bf1f1128dEAaB1492D45638DE0D3; // v3 NonfungiblePositionManager
    /// @dev Official UniversalRouter 2.1.2 (Uniswap `deploy-addresses/robinhood.json`) — the adapters' swap router.
