                    currency0: WETH, currency1: USDG, fee: V4_FEE, tickSpacing: V4_TICK_SPACING, hooks: address(0)
                }),
                refPool: POOL_FEE100,
                swapRouter: UNIVERSAL_ROUTER,
                swapExecutor: a.swapExecutor,
                owner: OWNER,
                rangeTicksBelow: RANGE_BELOW,
                rangeTicksAbove: RANGE_ABOVE,
