        );
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(b.vault);

        b.pairs = new MockPositionAdapter[](N_STOCKS);
        for (uint256 i; i < N_STOCKS; ++i) {
            address[] memory pairTokens = new address[](2);
            pairTokens[0] = address(usdg);
            pairTokens[1] = address(stocks[i]);
            b.pairs[i] = new MockPositionAdapter(pairTokens, b.vault, bytes32("uniswap-v3"), poolIds[i]);
            vaultC.addAdapter(b.pairs[i]);
        }
        vaultC.setKeeper(KEEPER, true);

        // Fund: owner seeds the stocks basket; demo user gets a spread of every stock.
        usdg.mint(OWNER, 50_000e6);
        usdg.mint(DEMO_USER, 100_000e6);
        usdg.approve(b.vault, type(uint256).max);
        for (uint256 i; i < N_STOCKS; ++i) {
            stocks[i].mint(OWNER, 100e18);
            stocks[i].mint(DEMO_USER, 50e18);
            stocks[i].approve(b.vault, type(uint256).max);
        }

        // Genesis deposit — owner-only; mints exactly STOCKS_GENESIS_SHARES (K).
        uint256[] memory boot = new uint256[](1 + N_STOCKS);
        boot[0] = 20_000e6;
        for (uint256 i; i < N_STOCKS; ++i) {
            boot[1 + i] = 10e18;
        }
        vaultC.deposit(b.basket, boot, STOCKS_GENESIS_SHARES, OWNER);
    }

    function _keeperStocks(StocksVault memory b) internal {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(b.vault);
        // Two of the five pairs get capital (NVDA, AAPL); the other three stay empty (idle-only legs).
        vaultC.deployTo(b.pairs[0], _pair(4_000e6, 4e18));
        vaultC.deployTo(b.pairs[1], _pair(3_000e6, 3e18));

        b.pairs[0].simulateFees(_pair(40e6, 0.04e18));
        b.pairs[1].simulateFees(_pair(30e6, 0.03e18));
    }

    /* ======================== vault C: "pons" (real, FablesRamp-hooked v4) ======================== */

    /// @dev Phase 3 (anvil #201 == OWNER). The vault goes through the OZ plugin like "demo" (its own validated
    ///      implementation, same DepositSplit); the eight adapters share the demo vault's stateless swap executor.
    function _deployPonsVault(address swapExecutor, address depositSplit, uint256 genUsdg)
        internal
        returns (PonsVault memory c)
    {
        c.basket = new address[](2);
        c.basket[0] = USDG;
        c.basket[1] = PONS;
        c.swapExecutor = swapExecutor;

        Options memory opts;
        opts.constructorData = abi.encode(depositSplit);
        c.vault = Upgrades.deployUUPSProxy(
            "MySunVaultUpgradeable.sol",
            abi.encodeCall(
                MySunVaultUpgradeable(address(0)).initialize,
                (OWNER, "sunPonsLP", "sunPonsLP", c.basket, OWNER, FEE_BPS, PONS_GENESIS_SHARES, PONS_MAX_TOTAL_SUPPLY)
            ),
            opts
        );
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(c.vault);

        c.adapters = new UniswapV4HookedAdapter[](N_PONS_ADAPTERS);
        for (uint256 i; i < N_PONS_ADAPTERS; ++i) {
            c.adapters[i] = new UniswapV4HookedAdapter(
                UniswapV4HookedAdapter.Config({
                    vault: c.vault,
                    positionManager: POSM,
                    poolKey: _ponsKey(),
                    refPool: REF_POOL_PONS,
                    swapRouter: UNIVERSAL_ROUTER,
                    swapExecutor: swapExecutor,
                    owner: OWNER,
                    rangeTicksBelow: PONS_RANGE,
                    rangeTicksAbove: PONS_RANGE,
                    twapWindow: TWAP_WINDOW,
                    maxSlippageBps: PONS_MAX_SLIPPAGE_BPS
                })
            );
            // The hooked v4 pool is the pair's deep venue (the v3 fee-10000 reference is thin): swap there.
            c.adapters[i].setSwapVenue(UniswapV4HookedAdapter.SwapVenue.V4_POOL);
            vaultC.addAdapter(IPositionAdapter(address(c.adapters[i])));
        }
        vaultC.setKeeper(KEEPER, true);

        // Genesis deposit — owner-only, REAL tokens funded by fork-demo-up.sh: a 50/50 basket at the reference
        // pool's spot, in kind; mints exactly PONS_GENESIS_SHARES (K). No adapter holds anything yet, so the
        // deposit split skips them all and the genesis stays idle for the keeper phase.
        IERC20(USDG).approve(c.vault, genUsdg);
        IERC20(PONS).approve(c.vault, GEN_PONS);
        vaultC.deposit(c.basket, _pair(genUsdg, GEN_PONS), PONS_GENESIS_SHARES, OWNER);
    }

    /// @dev Phase 4 (anvil #1 == KEEPER): equal slices of the vault's idle (floor of 1/8 per leg) into each adapter, in
    ///      ADAPTER order = pool order [PONS, USDG]. Each deploy runs its ratio swap on the hooked pool (TWAP-bounded,
    ///      hook-priced) and mints a real position; the < 8 wei per leg of division dust stays idle in the vault.
    function _keeperPons(PonsVault memory c) internal {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(c.vault);
        uint256 slicePons = IERC20(PONS).balanceOf(c.vault) / N_PONS_ADAPTERS;
        uint256 sliceUsdg = IERC20(USDG).balanceOf(c.vault) / N_PONS_ADAPTERS;
        for (uint256 i; i < N_PONS_ADAPTERS; ++i) {
            vaultC.deployTo(IPositionAdapter(address(c.adapters[i])), _pair(slicePons, sliceUsdg));
        }
    }

    /// @dev Proof the "pons" vault runs on the real hooked pool: each adapter owns exactly one live NFT minted on the
    ///      FablesRamp PONS/USDG pool, the vault's basket view reads through all eight, and no allowance stands.
    function _assertPonsPositions(PonsVault memory c) internal view {
        IPositionManagerMinimal posm = IPositionManagerMinimal(POSM);
        uint256 sumPons = IERC20(PONS).balanceOf(c.vault);
        uint256 sumUsdg = IERC20(USDG).balanceOf(c.vault);
        for (uint256 i; i < N_PONS_ADAPTERS; ++i) {
            address ad = address(c.adapters[i]);
            uint256 id = c.adapters[i].tokenId();
            require(id != 0, "pons adapter: no position minted");
            require(posm.balanceOf(ad) == 1, "pons adapter NFT count != 1");
            require(posm.ownerOf(id) == ad, "pons NFT not owned by adapter");
            (PoolKey memory key,) = posm.getPoolAndPositionInfo(id);
            require(keccak256(abi.encode(key)) == PONS_V4_POOL_ID, "pons NFT not on the hooked pool");
            require(posm.getPositionLiquidity(id) > 0, "pons position has no liquidity");
            (, uint256[] memory held) = c.adapters[i].position(); // pool order [PONS, USDG]
            sumPons += held[0];
            sumUsdg += held[1];
            _assertNoAllowances(c, ad);
        }
        (address[] memory t, uint256[] memory totals) = MySunVaultUpgradeable(c.vault).totalTokens();
        require(t[0] == USDG && t[1] == PONS, "pons vault registry order");
        require(totals[0] == sumUsdg && totals[1] == sumPons, "pons vault totals != idle + adapter positions");
        for (uint256 j; j < 2; ++j) {
            address token = c.basket[j];
            require(IERC20(token).balanceOf(c.swapExecutor) == 0, "executor holds tokens");
            require(IERC20(token).allowance(c.swapExecutor, PERMIT2) == 0, "executor -> Permit2 allowance");
            (uint160 inner,,) = IPermit2Minimal(PERMIT2).allowance(c.swapExecutor, token, UNIVERSAL_ROUTER);
            require(inner == 0, "executor Permit2 -> router allowance");
        }
    }

    function _assertNoAllowances(PonsVault memory c, address ad) internal view {
        for (uint256 j; j < 2; ++j) {
            address token = c.basket[j];
            require(IERC20(token).allowance(c.vault, ad) == 0, "vault -> adapter allowance");
            require(IERC20(token).allowance(ad, c.swapExecutor) == 0, "adapter -> executor allowance");
            require(IERC20(token).allowance(ad, PERMIT2) == 0, "adapter -> Permit2 allowance");
            (uint160 amount,,) = IPermit2Minimal(PERMIT2).allowance(ad, token, POSM);
            require(amount == 0, "adapter Permit2 -> PositionManager allowance");
        }
    }

    function _ponsKey() internal pure returns (PoolKey memory) {
        return PoolKey({
            currency0: PONS, currency1: USDG, fee: PONS_V4_FEE, tickSpacing: PONS_V4_TICK_SPACING, hooks: FABLES_RAMP
        });
    }

    /* ==================================== helpers ==================================== */

    /// @dev USDG worth `wethAmount` at the fee-100 pool's spot (token0 = WETH, token1 = USDG) — genesis sizing
    ///      only, the same helper the fork suites use.
    function _usdgFor(uint256 wethAmount) internal view returns (uint256) {
        (uint160 sqrtP,,,,,,) = IUniswapV3PoolMinimal(POOL_FEE100).slot0();
        return Math.mulDiv(Math.mulDiv(wethAmount, sqrtP, 1 << 96), sqrtP, 1 << 96);
    }

    /// @dev USDG worth `ponsAmount` at the v3 PONS/USDG reference pool's spot (token0 = PONS, token1 = USDG) — genesis
    ///      sizing only, the same helper test/fork/FablesRampPons.fork.t.sol uses.
    function _usdgForPons(uint256 ponsAmount) internal view returns (uint256) {
        (uint160 sqrtP,,,,,,) = IUniswapV3PoolMinimal(REF_POOL_PONS).slot0();
        return Math.mulDiv(Math.mulDiv(ponsAmount, sqrtP, 1 << 96), sqrtP, 1 << 96);
    }

    function _pair(uint256 x, uint256 y) internal pure returns (uint256[] memory arr) {
        arr = new uint256[](2);
        arr[0] = x;
        arr[1] = y;
    }

    /// @dev One entry of the v2 `vaults` array; name/symbol are read back from the chain.
    function _vaultJson(string memory key, string memory label, address vault) internal returns (string memory) {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(vault);
        string memory receiptObj = string.concat("receipt_", key);
        vm.serializeString(receiptObj, "name", vaultC.name());
        string memory receipt = vm.serializeString(receiptObj, "symbol", vaultC.symbol());

        string memory obj = string.concat("vault_", key);
        vm.serializeString(obj, "key", key);
        vm.serializeString(obj, "label", label);
        vm.serializeString(obj, "receipt", receipt);
        vm.serializeAddress(obj, "vault", vault);
        vm.serializeAddress(obj, "implementation", Upgrades.getImplementationAddress(vault));
        vm.serializeAddress(obj, "keeper", KEEPER);
        return vm.serializeAddress(obj, "demoUser", DEMO_USER);
    }

    function _logVault(string memory title, address vault) internal view {
        MySunVaultUpgradeable vaultC = MySunVaultUpgradeable(vault);
        console2.log(title);
        console2.log("vault (proxy)    :", vault);
        console2.log("implementation   :", Upgrades.getImplementationAddress(vault));
        console2.log("name / symbol    :", vaultC.name(), vaultC.symbol());
        console2.log("genesis shares   :", vaultC.genesisShares());
        console2.log("totalSupply      :", vaultC.totalSupply());
        console2.log("maxTotalSupply   :", vaultC.maxTotalSupply());
        (address[] memory t, uint256[] memory amt) = vaultC.totalTokens();
        for (uint256 i; i < t.length; ++i) {
            console2.log("total", IERC20Metadata(t[i]).symbol(), amt[i]);
        }
        for (uint256 i; i < t.length; ++i) {
            console2.log("idle ", IERC20Metadata(t[i]).symbol(), IERC20(t[i]).balanceOf(vault));
        }
    }

    function _logAdapter(string memory title, IPositionAdapter adapter, uint256 tokenId) internal view {
        (address[] memory t, uint256[] memory amt) = adapter.position();
        console2.log(title, address(adapter));
        console2.log("  LP NFT tokenId :", tokenId);
        for (uint256 i; i < t.length; ++i) {
            console2.log("  position", IERC20Metadata(t[i]).symbol(), amt[i]);
        }
    }

    function _logDemo(DemoVault memory a) internal view {
        _logVault("-- vault [demo] --", a.vault);
        console2.log("deposit splitter :", a.depositSplit);
        _logAdapter("adapter (v3 REAL):", IPositionAdapter(address(a.adapterV3)), a.adapterV3.tokenId());
        console2.log("  tickLower      :", int256(a.adapterV3.tickLower()));
        console2.log("  tickUpper      :", int256(a.adapterV3.tickUpper()));
        if (deployV4Hookless) {
            _logAdapter("adapter (v4 REAL):", IPositionAdapter(address(a.adapterV4)), a.adapterV4.tokenId());
            console2.log("  tickLower      :", int256(a.adapterV4.tickLower()));
            console2.log("  tickUpper      :", int256(a.adapterV4.tickUpper()));
        }
        console2.log("swap executor    :", a.swapExecutor);
        console2.log("native executor  :", a.nativeExecutor);
        console2.log("hook (FablesRampETH):", FABLES_RAMP_ETH);
        for (uint256 i; i < a.natives.length; ++i) {
            UniswapV4NativeEthAdapter ad = a.natives[i];
            _logAdapter("adapter (v4 native REAL):", IPositionAdapter(address(ad)), ad.tokenId());
            console2.log("  liquidity      :", IPositionManagerMinimal(POSM).getPositionLiquidity(ad.tokenId()));
            console2.log("  tickLower      :", int256(ad.tickLower()));
            console2.log("  tickUpper      :", int256(ad.tickUpper()));
        }
    }

    function _logStocks(StocksVault memory b) internal view {
        _logVault("-- vault [stocks] --", b.vault);
        for (uint256 i; i < b.pairs.length; ++i) {
            console2.log("adapter (pair)   :", MockToken(b.basket[1 + i]).symbol(), address(b.pairs[i]));
        }
    }

    function _logPons(PonsVault memory c) internal view {
        _logVault("-- vault [pons] --", c.vault);
        console2.log("TWAP reference   :", REF_POOL_PONS);
        console2.log("hook (FablesRamp):", FABLES_RAMP);
        for (uint256 i; i < c.adapters.length; ++i) {
            UniswapV4HookedAdapter ad = c.adapters[i];
            _logAdapter("adapter (v4 hooked REAL):", IPositionAdapter(address(ad)), ad.tokenId());
            console2.log("  liquidity      :", IPositionManagerMinimal(POSM).getPositionLiquidity(ad.tokenId()));
            console2.log("  tickLower      :", int256(ad.tickLower()));
            console2.log("  tickUpper      :", int256(ad.tickUpper()));
        }
    }
}

script/DeployAdapters.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {UniswapV3Adapter} from "contracts/adapters/UniswapV3Adapter.sol";
import {UniswapV4Adapter} from "contracts/adapters/UniswapV4Adapter.sol";
import {PoolKey} from "contracts/adapters/uniswap/v4/IPoolManagerMinimal.sol";
import {UniversalRouterSwapExecutor} from "contracts/swap/UniversalRouterSwapExecutor.sol";

/**
 * @notice Deploy the real Uniswap adapters (v3 + v4) for a deployed vault, one chain at a time. Nothing is
 *         signed here by anyone but the operator's own keystore account:
 *
 *   cd contracts
 *   VAULT=0x… forge script script/DeployAdapters.s.sol --rpc-url rhc --account <keystore> --broadcast
 *
 * Env:
 *   VAULT  — the vault PROXY the adapters serve (required — it is an immutable of both adapters; deploy the
 *            vault first, script/DeployMySunVaultUpgradeable.s.sol).
 *   OWNER  — the adapters' parameter admin (default: the broadcasting account; a production chain should
 *            use the team's multisig).
 *   KEEPER — optional keeper to enable in the same run (needs VAULT set and a broadcasting account that
 *            owns the vault).
 *   UR / PERMIT2 / POOL / NFPM — address overrides; the defaults are RHC mainnet (v3 fee-100 USDG/WETH pool as
 *   reference venue).
 *   WETH / USDG / POSM — v4-only address overrides (the v4 pool key currencies + v4 PositionManager; same RHC
 *   mainnet defaults); read only when DEPLOY_V4 is true.
 *   SWAP_EXECUTOR — optional already-deployed UniversalRouterSwapExecutor (stateless, no privileges) on exactly
 *   (UR, PERMIT2); unset = deploy a fresh one first in this run. Both adapters wire it immutably (their
 *   constructors reject an executor on another router / Permit2).
 *   DEPLOY_V4 — bool, default true (v3 + v4). `false` = v3 ONLY: no v4 adapter is constructed or registered
 *   (WETH / USDG / POSM are never read from the env — left zero — so no usable v4 wiring is needed) and
 *   `adapterV4` returns address(0).
 *   The RHC rehearsal runs with DEPLOY_V4=false (owner decision: v3-only there):
 *
 *   VAULT=0x… DEPLOY_V4=false forge script script/DeployAdapters.s.sol --rpc-url rhc --account <keystore> --broadcast
 *
 * When the broadcasting account owns the vault, the deployed adapters are added to it (and the keeper enabled);
 * otherwise the exact follow-up calls are printed for the vault owner. Parameters mirror the fork suites:
 * range ±300 ticks around TWAP, window 1800 s, max slippage 100 bps; the v4 pool is fee 500 / spacing 10 /
 * no hooks, its reference venue (and default swap pool) the v3 fee-100 pool.
 */
contract DeployAdapters is Script {
    /* --------------------------- venue defaults (notes/RHC_ADDRESSES.md) --------------------------- */
    address internal constant DEFAULT_UR = 0x204FAca1764B154221e35c0d20aBb3c525710498; // UniversalRouter 2.1.2
    address internal constant PERMIT2_CANONICAL = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    address internal constant DEFAULT_WETH = 0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73;
    address internal constant DEFAULT_USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168;
    address internal constant DEFAULT_POOL = 0x52e65B17fB6E5BA00Ed806f37Afcd2DaA50271Ca; // v3 fee 100
    address internal constant DEFAULT_NFPM = 0x73991a25C818Bf1f1128dEAaB1492D45638DE0D3;
    address internal constant DEFAULT_POSM = 0x58daec3116aae6D93017bAAea7749052E8a04fA7; // v4 PositionManager

    /* --------------------------------- parameters (fork-suite values) -------------------------------- */
    int24 internal constant RANGE_BELOW = 300;
    int24 internal constant RANGE_ABOVE = 300;
    uint32 internal constant TWAP_WINDOW = 1800;
    uint16 internal constant MAX_SLIPPAGE_BPS = 100;
    uint24 internal constant V4_FEE = 500;
    int24 internal constant V4_TICK_SPACING = 10;

    /// @dev Everything the run reads from the env (see the contract NatSpec for each variable).
    struct Params {
        address vault;
        address owner;
        address keeper;
        address ur;
        address permit2;
        address weth;
        address usdg;
        address pool;
        address nfpm;
        address posm;
        address executor;
        bool deployV4;
    }

    function run() external returns (address adapterV3, address adapterV4) {
        return _deploy(_paramsFromEnv());
    }

    function _paramsFromEnv() internal view returns (Params memory p) {
        p.deployV4 = vm.envOr("DEPLOY_V4", true);
        p.vault = vm.envAddress("VAULT");
        p.owner = vm.envOr("OWNER", msg.sender);
        p.keeper = vm.envOr("KEEPER", address(0));
        p.ur = vm.envOr("UR", DEFAULT_UR);
        p.permit2 = vm.envOr("PERMIT2", PERMIT2_CANONICAL);
        p.pool = vm.envOr("POOL", DEFAULT_POOL);
        p.nfpm = vm.envOr("NFPM", DEFAULT_NFPM);
        p.executor = vm.envOr("SWAP_EXECUTOR", address(0));
        // v4-only wiring: never read in v3-only mode (left zero), so no v4 env value can affect a v3 run.
        if (p.deployV4) {
            p.weth = vm.envOr("WETH", DEFAULT_WETH);
            p.usdg = vm.envOr("USDG", DEFAULT_USDG);
            p.posm = vm.envOr("POSM", DEFAULT_POSM);
        }
    }

    function _deploy(Params memory p) internal returns (address adapterV3, address adapterV4) {
        require(msg.sender == p.owner, "DeployAdapters: OWNER must be the broadcasting account");

        vm.startBroadcast();
        if (p.executor == address(0)) {
            p.executor = address(new UniversalRouterSwapExecutor(p.ur, p.permit2));
        }
        adapterV3 = address(
            new UniswapV3Adapter(
                UniswapV3Adapter.Config({
                    vault: p.vault,
                    pool: p.pool,
                    positionManager: p.nfpm,
                    swapRouter: p.ur,
                    permit2: p.permit2,
                    swapExecutor: p.executor,
                    owner: p.owner,
                    rangeTicksBelow: RANGE_BELOW,
                    rangeTicksAbove: RANGE_ABOVE,
                    twapWindow: TWAP_WINDOW,
                    maxSlippageBps: MAX_SLIPPAGE_BPS
                })
            )
        );
        if (p.deployV4) {
            adapterV4 = address(
                new UniswapV4Adapter(
                    UniswapV4Adapter.Config({
                        vault: p.vault,
                        positionManager: p.posm,
                        poolKey: PoolKey({
                            currency0: p.weth,
                            currency1: p.usdg,
                            fee: V4_FEE,
                            tickSpacing: V4_TICK_SPACING,
                            hooks: address(0)
                        }),
                        refPool: p.pool,
                        swapRouter: p.ur,
                        swapExecutor: p.executor,
                        owner: p.owner,
                        rangeTicksBelow: RANGE_BELOW,
                        rangeTicksAbove: RANGE_ABOVE,
                        twapWindow: TWAP_WINDOW,
                        maxSlippageBps: MAX_SLIPPAGE_BPS
                    })
                )
            );
        }

        bool canSetup = p.vault.code.length > 0 && MySunVaultUpgradeable(p.vault).owner() == msg.sender;
        if (canSetup) {
            MySunVaultUpgradeable(p.vault).addAdapter(IPositionAdapter(adapterV3));
            if (p.deployV4) MySunVaultUpgradeable(p.vault).addAdapter(IPositionAdapter(adapterV4));
            if (p.keeper != address(0)) MySunVaultUpgradeable(p.vault).setKeeper(p.keeper, true);
        }
        vm.stopBroadcast();

        _log(p, adapterV3, adapterV4, canSetup);
    }

    function _log(Params memory p, address adapterV3, address adapterV4, bool canSetup) internal view {
        console2.log("mode      :", p.deployV4 ? "v3 + v4" : "v3 ONLY (DEPLOY_V4=false) - no v4 adapter deployed");
        console2.log("chainId   :", block.chainid);
        console2.log("vault     :", p.vault);
        console2.log("adapterV3 :", adapterV3);
        if (p.deployV4) {
            console2.log("adapterV4 :", adapterV4);
        } else {
            console2.log("adapterV4 : none (skipped: DEPLOY_V4=false)");
        }
        console2.log("owner     :", p.owner);
        console2.log("ur        :", p.ur);
        console2.log("executor  :", p.executor);
        console2.log("pool (v3) :", p.pool);
        console2.log("nfpm      :", p.nfpm);
        if (p.deployV4) console2.log("posm      :", p.posm);
        if (canSetup) {
            if (p.deployV4) {
                console2.log("vault: both adapters added (v3 + v4); keeper enabled:", p.keeper != address(0));
            } else {
                console2.log("vault: ONLY the v3 adapter added (no v4); keeper enabled:", p.keeper != address(0));
            }
        } else {
            console2.log("vault has no code OR is not owned by the sender - run these from the vault owner:");
            console2.log("  vault.addAdapter(", adapterV3);
            if (p.deployV4) console2.log("  vault.addAdapter(", adapterV4);
            if (p.keeper != address(0)) {
                console2.log("  vault.setKeeper(keeper, true) with keeper:", p.keeper);
            }
        }
        console2.log("next: the zap periphery (script/DeployPeriphery.s.sol), then the keeper service");
    }
}

script/DeployCreate3Factory.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {PoolmigoCreate3} from "contracts/periphery/PoolmigoCreate3.sol";

/**
 * @notice Deploys the PoolmigoCreate3 factory — run ONCE per chain, as the FIRST transaction of a
 * dedicated deployer account, so the factory lands at the same address everywhere (nonce 0).
 * Every later deterministic deployment keys off this address (and off the deployer that calls it:
 * the factory binds each salt to its caller, so vaults must also be deployed by one fixed account).
 *
 * Local anvil:
 *   forge script script/DeployCreate3Factory.s.sol --rpc-url http://127.0.0.1:8548 \
 *     --private-key $ANVIL_DEV_KEY --broadcast        # public test key — LOCAL ONLY
 *
 * Real network (keystore only — never a plaintext key):
 *   forge script script/DeployCreate3Factory.s.sol --rpc-url <rpc> \
 *     --account <keystoreName> --sender <address> --broadcast
 *
 * Prints `POOLMIGO_CREATE3_FACTORY=<address>` for script/DeployDeterministic.s.sol.
 */
contract DeployCreate3Factory is Script {
    function run() external returns (address factory) {
        vm.startBroadcast();
        uint256 nonce = vm.getNonce(msg.sender);
        if (nonce != 0) {
            console2.log(
                "WARNING: deployer nonce is", nonce, "-> factory address will NOT match a fresh-account deployment"
            );
        } else {
            console2.log("deployer nonce 0: factory address is chain-independent (same account on every chain)");
        }
        factory = address(new PoolmigoCreate3());
        vm.stopBroadcast();
        console2.log("POOLMIGO_CREATE3_FACTORY=%s", factory);
    }
}

script/DeployDepositSplit.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {DepositSplit} from "contracts/periphery/DepositSplit.sol";

/**
 * @notice Resolves the {DepositSplit} a vault implementation pins at construction (its immutable): the `DEPOSIT_SPLIT`
 *         env address if set (must have code), else a fresh deployment by the broadcasting account. Call it INSIDE
 *         the broadcast, before the implementation is created. The splitter is stateless and ownerless, so reusing
 *         one per chain and deploying a fresh one are equivalent; reuse keeps the chain's registry short.
 */
abstract contract DepositSplitEnv is Script {
    function _depositSplit() internal returns (address split) {
        split = vm.envOr("DEPOSIT_SPLIT", address(0));
        if (split == address(0)) {
            split = address(new DepositSplit());
        } else {
            require(split.code.length > 0, "DEPOSIT_SPLIT has no code");
        }
    }
}

/**
 * @notice Deploys the stateless {DepositSplit} once per chain — the vault-implementation constructor argument
 *         (deposit-deploy, T2d). Run it before the vault scripts and export the printed address as `DEPOSIT_SPLIT`
 *         (`DeployMySunVaultUpgradeable` / `DeployDeterministic` / `UpgradeExample` deploy one themselves if unset).
 *         No constructor arguments, no owner, nothing to wire. Runbook: notes/DEPLOY-RHC.md.
 *
 *   forge script script/DeployDepositSplit.s.sol --rpc-url <rpc> --account <keystore> --sender <addr> --broadcast
 */
contract DeployDepositSplit is Script {
    function run() external returns (address split) {
        vm.startBroadcast();
        split = address(new DepositSplit());
        vm.stopBroadcast();
        console2.log("DEPOSIT_SPLIT=%s", split);
    }
}

script/DeployDeterministic.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {console2} from "forge-std/Script.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {PoolmigoCreate3} from "contracts/periphery/PoolmigoCreate3.sol";
import {DepositSplitEnv} from "./DeployDepositSplit.s.sol";

/**
 * @notice Deterministic vault deployment: the UUPS proxy lands on
 * `CREATE3_FACTORY.create3Address(deployer, SALT)` — the same address on every chain where the factory
 * sits at the same address AND the same deployer account broadcasts this script — while the
 * implementation is a plain per-chain CREATE (its address may differ; the proxy stores it).
 * Salt default: keccak256("poolmigo.vault.v1") — the registered salt text predates the MySun rebrand and stays
 * unchanged (renaming it would move the predicted address). The factory binds the salt to the caller
 * (effective salt = keccak256(SALT ‖ deployer)), so nobody else can squat the team's documented salts;
 * the flip side is that a different deployer lands on a different address — always deploy from the
 * project's one dedicated deployer account (notes/NAMING.md, salt registry).
 * ONE SALT PER VAULT PER CHAIN: a second vault (e.g. the stocks basket) needs its own salt —
 * registry in notes/NAMING.md (e.g. SALT=$(cast keccak "poolmigo.vault.stocks.v1")).
 *
 * Always `forge clean && forge build` first (the OZ validator needs a single fresh build-info).
 *
 *   CREATE3_FACTORY=0x... OWNER=0x... TREASURY=0x... FEE_BPS=1000 TOKENS=0x..,0x.. \
 *   GENESIS_SHARES=10000000000000000000000 MAX_TOTAL_SUPPLY=500000000000000000000000 \
 *   forge script script/DeployDeterministic.s.sol --rpc-url <rpc> \
 *     --account <keystoreName> --sender <address> --broadcast
 *
 * Env: CREATE3_FACTORY, OWNER, TREASURY, FEE_BPS, TOKENS (comma-separated), GENESIS_SHARES (K, non-zero),
 *      MAX_TOTAL_SUPPLY (0 = uncapped);
 *      NAME / SYMBOL (receipt token, optional, default "sunEthLP" / "sunEthLP");
 *      SALT (bytes32, optional); LABEL (optional log tag, so two runs can be diffed);
 *      DEPOSIT_SPLIT (optional: the chain's DepositSplit, the implementation's constructor arg; unset = deploy one).
 * The proxy address depends only on deployer + salt (CREATE3), never on the implementation or the splitter; the
 * factory must still be the deployer's FIRST tx (nonce 0) — a splitter deployed here comes after it.
 */
contract DeployDeterministic is DepositSplitEnv {
    struct Params {
        address owner;
        string name;
        string symbol;
        address treasury;
        uint16 feeBps;
        address[] tokens;
        uint256 genesisShares;
        uint256 maxTotalSupply;
        bytes32 salt;
        string label;
    }

    function run() external returns (address proxy, address implementation) {
        Params memory p = _readParams();
        PoolmigoCreate3 factory = PoolmigoCreate3(vm.envAddress("CREATE3_FACTORY"));
        bytes memory initData = abi.encodeCall(
            MySunVaultUpgradeable(address(0)).initialize,
            (p.owner, p.name, p.symbol, p.tokens, p.treasury, p.feeBps, p.genesisShares, p.maxTotalSupply)
        );

        // OZ upgrade-safety validation (needs a single fresh build-info — clean-build first).
        Options memory opts;
        Upgrades.validateImplementation("MySunVaultUpgradeable.sol", opts);

        vm.startBroadcast();
        // The proxy address depends on the broadcasting deployer (salt bound to msg.sender at the factory).
        (, address deployer,) = vm.readCallers();
        address predicted = factory.create3Address(deployer, p.salt);
        address depositSplit = _depositSplit();
        implementation = address(new MySunVaultUpgradeable(depositSplit));
        bytes memory proxyCode = abi.encodePacked(type(ERC1967Proxy).creationCode, abi.encode(implementation, initData));
        proxy = factory.deploy(p.salt, proxyCode);
        vm.stopBroadcast();

        _verify(p, proxy, implementation, predicted);
        _log(p, proxy, implementation, address(factory), predicted);
        console2.log("[%s] POOLMIGO_DEPLOYER=%s", p.label, deployer);
        console2.log("[%s] POOLMIGO_DEPOSIT_SPLIT=%s", p.label, depositSplit);
    }

    function _readParams() internal view returns (Params memory p) {
        p.owner = vm.envAddress("OWNER");
        p.name = vm.envOr("NAME", string("sunEthLP"));
        p.symbol = vm.envOr("SYMBOL", string("sunEthLP"));
        p.treasury = vm.envAddress("TREASURY");
        p.feeBps = uint16(vm.envUint("FEE_BPS"));
        p.tokens = vm.envAddress("TOKENS", ",");
        p.genesisShares = vm.envUint("GENESIS_SHARES");
        p.maxTotalSupply = vm.envUint("MAX_TOTAL_SUPPLY");
        p.salt = vm.envOr("SALT", keccak256("poolmigo.vault.v1"));
        p.label = vm.envOr("LABEL", string("deploy"));
    }

    function _verify(Params memory p, address proxy, address implementation, address predicted) internal view {
        require(proxy == predicted, "CREATE3 address mismatch");
        require(Upgrades.getImplementationAddress(proxy) == implementation, "EIP-1967 slot mismatch");
        MySunVaultUpgradeable vault = MySunVaultUpgradeable(proxy);
        require(
            vault.owner() == p.owner && vault.treasury() == p.treasury && vault.performanceFeeBps() == p.feeBps
                && vault.genesisShares() == p.genesisShares && vault.maxTotalSupply() == p.maxTotalSupply,
            "initialize state mismatch"
        );
        require(
            keccak256(bytes(vault.name())) == keccak256(bytes(p.name))
                && keccak256(bytes(vault.symbol())) == keccak256(bytes(p.symbol)),
            "receipt name/symbol mismatch"
        );
    }

    function _log(Params memory p, address proxy, address implementation, address factory, address predicted)
        internal
        view
    {
        console2.log("[%s] POOLMIGO_PROXY=%s", p.label, proxy);
        console2.log("[%s] POOLMIGO_IMPL=%s", p.label, implementation);
        console2.log("[%s] POOLMIGO_FACTORY=%s", p.label, factory);
        console2.log("[%s] POOLMIGO_PREDICTED=%s", p.label, predicted);
        console2.log("[%s] POOLMIGO_RECEIPT=%s", p.label, string.concat(p.name, " / ", p.symbol));
    }
}

script/DeployMySunVaultUpgradeable.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {console2} from "forge-std/Script.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {DepositSplitEnv} from "./DeployDepositSplit.s.sol";

/**
 * @notice Deploys the UUPS proxy + MySunVaultUpgradeable implementation, validated by the OZ plugin.
 *
 * Always `forge clean && forge build` first (stale build-info aborts the OZ validator).
 *
 * LOCAL anvil (throwaway dev key is acceptable):
 *   forge script script/DeployMySunVaultUpgradeable.s.sol \
 *     --rpc-url http://127.0.0.1:8546 --broadcast --private-key $ANVIL_DEV_KEY
 *
 * Robinhood TESTNET (chain 46630 — key stays in an encrypted keystore, never plaintext):
 *   forge script script/DeployMySunVaultUpgradeable.s.sol \
 *     --rpc-url https://rpc.testnet.chain.robinhood.com \
 *     --account <keystoreName> --sender <yourAddress> --broadcast
 *
 * Env params:
 *   OWNER     — vault owner + upgrade authority (multisig behind timelock on mainnet)
 *   NAME      — receipt-token name   (optional, default "sunEthLP"; per vault — notes/NAMING.md)
 *   SYMBOL    — receipt-token symbol (optional, default "sunEthLP"; per vault — notes/NAMING.md)
 *   TREASURY  — performance-fee recipient
 *   FEE_BPS   — performance fee in bps (<= 3000)
 *   TOKENS    — comma-separated basket token addresses, e.g. "0xUSDG,0xWETH" (1..8, no duplicates)
 *   GENESIS_SHARES   — K, shares minted by the owner-gated genesis deposit (non-zero, 18-dp raw units;
 *                      set from the team's one-time off-chain valuation so display starts ≈$1/share)
 *   MAX_TOTAL_SUPPLY — receipt-token supply cap (raw units; 0 = uncapped; if set, >= GENESIS_SHARES)
 *   DEPOSIT_SPLIT    — optional: the chain's DepositSplit (implementation constructor arg, immutable;
 *                      `script/DeployDepositSplit.s.sol`). Unset = a fresh one is deployed first.
 */
contract DeployMySunVaultUpgradeable is DepositSplitEnv {
    function run() external returns (address proxy) {
        address owner = vm.envAddress("OWNER");
        string memory name = vm.envOr("NAME", string("sunEthLP"));
        string memory symbol = vm.envOr("SYMBOL", string("sunEthLP"));
        address treasury = vm.envAddress("TREASURY");
        uint16 feeBps = uint16(vm.envUint("FEE_BPS"));
        address[] memory tokens = vm.envAddress("TOKENS", ",");
        uint256 genesisShares = vm.envUint("GENESIS_SHARES");
        uint256 maxTotalSupply = vm.envUint("MAX_TOTAL_SUPPLY");

        vm.startBroadcast();
        address depositSplit = _depositSplit();
        Options memory opts;
        opts.constructorData = abi.encode(depositSplit);
        proxy = Upgrades.deployUUPSProxy(
            _artifact(),
            abi.encodeCall(
                MySunVaultUpgradeable(address(0)).initialize,
                (owner, name, symbol, tokens, treasury, feeBps, genesisShares, maxTotalSupply)
            ),
            opts
        );
        vm.stopBroadcast();

        console2.log("MySun vault (proxy) deployed at:", proxy);
        console2.log("  implementation:", Upgrades.getImplementationAddress(proxy), _artifact());
        console2.log("  deposit splitter:", depositSplit);
        console2.log("  receipt :", name, symbol);
        console2.log("  owner   :", owner);
        console2.log("  treasury:", treasury);
        console2.log("  fee bps :", feeBps);
        console2.log("  genesis shares (K):", genesisShares);
        console2.log("  max total supply  :", maxTotalSupply);
        for (uint256 i; i < tokens.length; ++i) {
            console2.log("  token   :", tokens[i]);
        }
    }

    /// @dev Implementation artifact the OZ plugin validates and deploys. The `initialize` selector is shared with the
    ///      legacy artifact (same inherited function), so only this name differs in the legacy script.
    function _artifact() internal pure virtual returns (string memory) {
        return "MySunVaultUpgradeable.sol";
    }
}

script/DeployPeriphery.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {MySunZapIn} from "contracts/periphery/MySunZapIn.sol";
import {MySunZapOut} from "contracts/periphery/MySunZapOut.sol";
import {PlanExecutor} from "contracts/periphery/PlanExecutor.sol";
import {IMySunVault} from "contracts/interfaces/IMySunVault.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";

/**
 * @notice Deploys the periphery (MySunZapIn + MySunZapOut + the strategy-layer PlanExecutor) for one vault to a
 *         real network and wires it up —
 *         nothing is signed by anyone but the operator's own keystore account (`--account`, never a
 *         plaintext key). Runbook: notes/DEPLOY-RHC.md.
 *
 * Always `forge clean && forge build` first (the OZ-plugin pitfall does not apply here — no proxy — but the
 * clean build keeps deploy scripts deterministic).
 *
 * Robinhood MAINNET (chain 4663):
 *   cd contracts
 *   export VAULT=0x... OWNER=0x...   # OWNER = the vault owner / multisig that will administer the zaps
 *   forge script script/DeployPeriphery.s.sol --rpc-url rhc --account <keystore> --sender <addr> --broadcast
 *
 * Env params:
 *   VAULT       — the deployed MySun vault proxy whose shares the zaps serve (required; must answer
 *                 tokens() with a non-empty basket). Both zaps are registered to it and the PlanExecutor is
 *                 bound to it (immutable); the "stocks"-style vaults with mock tokens are NOT registered on the
 *                 zaps (no venue to route through).
 *   OWNER       — periphery owner (zap registry admin + PlanExecutor keeper admin). Default: the broadcasting
 *                 sender. If it differs from the sender, the script still deploys but prints the setup calls to
 *                 run FROM the owner account (registerVault + setRoute + PlanExecutor.setKeeper are onlyOwner).
 *   PLAN_KEEPER — optional: the keeper service address whitelisted on the PlanExecutor (`setKeeper`) — only when
 *                 sender == OWNER; otherwise the call is printed.
 *   NEW_OWNER   — optional: transfer ownership of all three to it at the end (Ownable2Step: it must then call
 *                 acceptOwnership()). Use when deploying from a hot account but the multisig should own it.
 *   UR         — UniversalRouter 2.1.x. Default: the RHC-wired official 2.1.2.
 *   PERMIT2    — Permit2. Default: canonical.
 *   TOKEN_IN / TOKEN_OUT — the ordered route pair. Default USDG → WETH (zap-in buys WETH with USDG; the
 *                          zap-out route is the reverse of it).
 *   ROUTE_FEE  — v3 fee tier of the route pool. Default 100.
 *   ROUTE_POOL — the route pool. Default: the deepest RHC USDG/WETH venue (v3 fee-100).
 *
 * Ownership: the PlanExecutor only works once it is a VAULT keeper (`vault.setKeeper(planExecutor, true)` — vault
 * owner only). The script grants it only when the sender IS the vault owner (`vault.owner()`, independent of OWNER);
 * otherwise it prints the call to run from the vault owner (multisig).
 *
 * Route params are pinned to the published defaults: TWAP window 600 s, max slippage 50 bps, max adverse
 * spot-vs-TWAP deviation 50 bps (research/zap-sandwich/findings.md).
 */
contract DeployPeriphery is Script {
    /* ---------------- verified RHC defaults (notes/RHC_ADDRESSES.md — never invent one) ---------------- */
    address internal constant DEFAULT_UR = 0x204FAca1764B154221e35c0d20aBb3c525710498; // official 2.1.2, RHC-wired
    address internal constant DEFAULT_PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3; // canonical
    address internal constant DEFAULT_USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168; // 6 dp
    address internal constant DEFAULT_WETH = 0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73; // 18 dp
    address internal constant DEFAULT_POOL_FEE100 = 0x52e65B17fB6E5BA00Ed806f37Afcd2DaA50271Ca; // deepest USDG/WETH

    uint16 internal constant ZAP_TWAP_WINDOW = 600;
    uint16 internal constant ZAP_SLIP_BPS = 50;
    uint16 internal constant ZAP_DEV_BPS = 50;

    function run() external returns (address zapIn, address zapOut, address planExecutor) {
        address vault = vm.envAddress("VAULT");
        address owner = vm.envOr("OWNER", msg.sender);
        address newOwner = vm.envOr("NEW_OWNER", address(0));
        address ur = vm.envOr("UR", DEFAULT_UR);
        address permit2 = vm.envOr("PERMIT2", DEFAULT_PERMIT2);
        address tokenIn = vm.envOr("TOKEN_IN", DEFAULT_USDG);
        address tokenOut = vm.envOr("TOKEN_OUT", DEFAULT_WETH);
        uint24 fee = uint24(vm.envOr("ROUTE_FEE", uint256(100)));
        address pool = vm.envOr("ROUTE_POOL", DEFAULT_POOL_FEE100);

        require(vault != address(0), "VAULT required");
        require(vault.code.length > 0, "VAULT has no code - deploy the vault first");

        bool canSetup = owner == msg.sender;
        vm.startBroadcast();
        zapIn = address(new MySunZapIn(ur, permit2, owner));
        zapOut = address(new MySunZapOut(ur, permit2, owner));
        if (canSetup) {
            MySunZapIn(zapIn).registerVault(vault);
            MySunZapIn(zapIn).setRoute(tokenIn, tokenOut, fee, pool, ZAP_TWAP_WINDOW, ZAP_SLIP_BPS, ZAP_DEV_BPS);
            MySunZapOut(zapOut).registerVault(vault);
            MySunZapOut(zapOut).setRoute(tokenOut, tokenIn, fee, pool, ZAP_TWAP_WINDOW, ZAP_SLIP_BPS, ZAP_DEV_BPS);
        }
        planExecutor = _deployPlanExecutor(vault, owner, canSetup);
        if (canSetup && newOwner != address(0) && newOwner != owner) {
            MySunZapIn(zapIn).transferOwnership(newOwner);
            MySunZapOut(zapOut).transferOwnership(newOwner);
            PlanExecutor(planExecutor).transferOwnership(newOwner);
        }
        vm.stopBroadcast();

        console2.log("== MySun periphery (zaps + plan executor) ==");
        console2.log("chainId       :", block.chainid);
        console2.log("vault         :", vault);
        console2.log("zap-in        :", zapIn);
        console2.log("zap-out       :", zapOut);
        console2.log("plan-executor :", planExecutor);
        console2.log("owner         :", owner);
        console2.log("route         :", tokenIn);
        console2.log("              ->", tokenOut);
        console2.log("fee           :", fee);
        console2.log("pool          :", pool);
        if (canSetup) {
            console2.log("registered + routes set (sender == owner)");
        } else {
            console2.log("sender != OWNER: run these FROM the owner account, then acceptOwnership if needed:");
            console2.log("  zapIn.registerVault(vault);         zapIn.setRoute(tokenIn, tokenOut, ...)");
            console2.log("  zapOut.registerVault(vault);        zapOut.setRoute(tokenOut, tokenIn, ...)");
            console2.log("  planExecutor.setKeeper(<keeper service>, true)");
        }
        _logPlanExecutorWiring(vault, canSetup);
        if (canSetup && newOwner != address(0) && newOwner != owner) {
            console2.log("pending owner (call acceptOwnership from it):", newOwner);
        }
        console2.log(
            "next: add zapIn / zapOut / planExecutor to shared/deployments.json under chains.<chainId>.periphery;"
        );
        console2.log("      make sure the plan executor holds a vault-keeper slot + has its own keeper (setKeeper)");
    }

    /// @dev PlanExecutor bound to `vault`, owned by `owner`. Vault-keeper slot only when the sender IS the vault owner
    ///      (`vault.owner()` — not necessarily OWNER); its own keeper (PLAN_KEEPER) only when sender == OWNER.
    function _deployPlanExecutor(address vault, address owner, bool canSetup) internal returns (address planExecutor) {
        planExecutor = address(new PlanExecutor(IMySunVault(vault), owner));
        if (MySunVaultUpgradeable(vault).owner() == msg.sender) {
            MySunVaultUpgradeable(vault).setKeeper(planExecutor, true);
        }
        address planKeeper = vm.envOr("PLAN_KEEPER", address(0));
        if (canSetup && planKeeper != address(0)) {
            PlanExecutor(planExecutor).setKeeper(planKeeper, true);
        }
    }

    function _logPlanExecutorWiring(address vault, bool canSetup) internal view {
        address planKeeper = vm.envOr("PLAN_KEEPER", address(0));
        if (canSetup && planKeeper != address(0)) {
            console2.log("plan-executor keeper set:", planKeeper);
        } else if (canSetup) {
            console2.log("PLAN_KEEPER unset: run planExecutor.setKeeper(<keeper service>, true) FROM the owner");
        }
        if (MySunVaultUpgradeable(vault).owner() == msg.sender) {
            console2.log("plan executor granted a vault-keeper slot (sender == vault owner)");
        } else {
            console2.log("sender != vault owner: run FROM the vault owner: vault.setKeeper(planExecutor, true)");
        }
    }
}

script/DeployPonsVault.s.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Script, console2} from "forge-std/Script.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {MySunVaultUpgradeable} from "contracts/MySunVaultUpgradeable.sol";
import {IPositionAdapter} from "contracts/interfaces/IPositionAdapter.sol";
import {IAdapterFees} from "contracts/interfaces/IAdapterFees.sol";
import {PoolKey} from "contracts/adapters/uniswap/v4/IPoolManagerMinimal.sol";
import {DepositSplit} from "contracts/periphery/DepositSplit.sol";
import {UniswapV4HookedAdapter} from "contracts/adapters/UniswapV4HookedAdapter.sol";

/// @notice OPS (4663 mainnet): deploy a SECOND vault — sunPonsLP — mirroring the demo chain's "pons" vault
///         (script/DemoLocalFork.s.sol) exactly: basket [USDG, PONS], treasury = owner, perf fee 1000 bps,
///         genesis K 8,000 sunPonsLP, cap 500,000 sunPonsLP, OWNER-only deposit split; keepers = burner +
///         ops keeper (same whitelist as sunEthLP); 3 UniswapV4HookedAdapter on the REAL mainnet PONS/USDG
///         FablesRamp pool (poolId 0x486435a1…, hook 0x08E5…, dynamic fee, spacing 60), range ±600 ticks,
///         TWAP 1800 s, slippage 200 bps, venue V4_POOL, shared UniversalRouter swap executor.
///   forge script script/DeployPonsVault.s.sol --rpc-url rhc --sender <owner> \
///     --account mysun-rehearsal --password-file <path> --broadcast
///   Env: OWNER (default msg.sender). No genesis deposit here — the first owner deposit mints the K share
///         constant (the owner funds PONS/USDG in kind out-of-band when ready).
contract DeployPonsVault is Script {
    address internal constant OWNER = 0x27447D6F3eCAA5f0c6b89a5b3D2FA03ff3392eaa; // burner — owner / treasury / keeper
    address internal constant OPS_KEEPER = 0x0856965c4A6346C5E33352A670CEb6E569DeF678; // same whitelist as sunEthLP
    address internal constant PONS = 0x39dBED3a2bd333467115dE45665cC57F813C4571; // currency0 / basket token1
    address internal constant USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168; // currency1 / basket token0
    address internal constant FABLES_RAMP = 0x08E52564Bad99E05a694b4809F397edcA417A080; // bits 0x2080
    address internal constant POSM = 0x58daec3116aae6D93017bAAea7749052E8a04fA7; // v4 PositionManager
    address internal constant REF_POOL_PONS = 0x7A192E71564ec66eE0763e328a3Ac274942dE4e1; // v3 fee-10000 TWAP ref
    address internal constant UNIVERSAL_ROUTER = 0x204FAca1764B154221e35c0d20aBb3c525710498; // UR 2.1.2
    address internal constant SWAP_EXECUTOR = 0x413a67ca4E83A4782F7745858979fE059ccbB431; // shared ERC-20 executor
    uint24 internal constant V4_FEE = 0x800000; // DYNAMIC_FEE_FLAG — the hook resolves each swap's fee
    int24 internal constant V4_TICK_SPACING = 60;
    int24 internal constant RANGE_TICKS = 600; // ±600 around the TWAP, snapped outward to spacing 60
    uint32 internal constant TWAP_WINDOW = 1800;
    uint16 internal constant MAX_SLIPPAGE_BPS = 200;
    uint16 internal constant FEE_BPS = 1000; // 10% performance fee (mirrors sunEthLP + demo pons)
    uint256 internal constant GENESIS_SHARES = 8_000e18; // demo pons genesis K
    uint256 internal constant MAX_TOTAL_SUPPLY = 500_000e18; // demo pons cap
    uint256 internal constant N_ADAPTERS = 3; // test set (demo has 8)

    function run() external {
        address owner = vm.envOr("OWNER", OWNER);
        require(msg.sender == owner, "DeployPonsVault: OWNER must be the broadcasting account");

        Options memory opts;
        opts.constructorData = abi.encode(address(new DepositSplit()));

        address[] memory basket = new address[](2);
        basket[0] = USDG;
        basket[1] = PONS;

        console2.log("chainId              :", block.chainid);
        console2.log("deploying sunPonsLP   : basket [USDG, PONS]");
        console2.log("  fee bps             :", FEE_BPS);
        console2.log("  genesis K           :", GENESIS_SHARES);

        vm.startBroadcast();
        address vaultAddr = Upgrades.deployUUPSProxy(
            "MySunVaultUpgradeable.sol",
            abi.encodeCall(
                MySunVaultUpgradeable(address(0)).initialize,
                (owner, "sunPonsLP", "sunPonsLP", basket, owner, FEE_BPS, GENESIS_SHARES, MAX_TOTAL_SUPPLY)
            ),
            opts
        );
        console2.log("sunPonsLP vault       :", vaultAddr);
        MySunVaultUpgradeable vault = MySunVaultUpgradeable(vaultAddr);

        vault.setKeeper(OWNER, true);
        vault.setKeeper(OPS_KEEPER, true);
        console2.log("keepers              :", OWNER, "+", OPS_KEEPER);

        PoolKey memory key = PoolKey({
            currency0: PONS,
            currency1: USDG,
            fee: V4_FEE,
            tickSpacing: V4_TICK_SPACING,
            hooks: FABLES_RAMP
        });

        UniswapV4HookedAdapter[] memory added = new UniswapV4HookedAdapter[](N_ADAPTERS);
        for (uint256 i; i < N_ADAPTERS; ++i) {
            added[i] = new UniswapV4HookedAdapter(
                UniswapV4HookedAdapter.Config({
                    vault: vaultAddr,
                    positionManager: POSM,
                    poolKey: key,
                    refPool: REF_POOL_PONS,
                    swapRouter: UNIVERSAL_ROUTER,
                    swapExecutor: SWAP_EXECUTOR,
                    owner: owner,
                    rangeTicksBelow: RANGE_TICKS,
                    rangeTicksAbove: RANGE_TICKS,
                    twapWindow: TWAP_WINDOW,
                    maxSlippageBps: MAX_SLIPPAGE_BPS
                })
            );
            added[i].setSwapVenue(UniswapV4HookedAdapter.SwapVenue.V4_POOL);
            vault.addAdapter(IPositionAdapter(address(added[i])));
            console2.log("added hooked adapter :", address(added[i]));
        }
        vm.stopBroadcast();

        require(MySunVaultUpgradeable(vaultAddr).owner() == owner, "DeployPonsVault: owner mismatch");
        require(MySunVaultUpgradeable(vaultAddr).isKeeper(OWNER), "DeployPonsVault: keeper not whitelisted");
        require(MySunVaultUpgradeable(vaultAddr).isKeeper(OPS_KEEPER), "DeployPonsVault: ops keeper not whitelisted");
        for (uint256 i; i < N_ADAPTERS; ++i) {
            UniswapV4HookedAdapter a = added[i];
            require(vault.isAdapter(address(a)), "DeployPonsVault: NOT registered");
            require(address(a.VAULT()) == vaultAddr, "DeployPonsVault: wrong vault");
            require(a.HOOKS() == FABLES_RAMP, "DeployPonsVault: hook mismatch");
            require(a.supportsInterface(type(IAdapterFees).interfaceId), "DeployPonsVault: missing IAdapterFees");
            console2.log("verify OK            :", address(a));
        }
        console2.log("final adapterCount   :", vault.adapterCount());
        console2.log("next                 : owner funds PONS+USDG -> vault.deposit (genesis K) -> keeper deployTo per adapter");
    }
}

