        }
        uint256 ratioX128 = Math.mulDiv(sqrtPriceX96, sqrtPriceX96, 1 << 64);
        return zeroForOne ? amountIn.mulDiv(ratioX128, 1 << 128) : amountIn.mulDiv(1 << 128, ratioX128);
    }
}

