// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

/// @notice Action ids understood by the v4 PositionManager's `modifyLiquidities` (public v4-periphery action
///         encoding). Only the subset the adapter uses. Exercised end-to-end against the deployed RHC
///         PositionManager by `test/fork/UniswapV4Adapter.fork.t.sol`.
///
///         Params ABI per action:
///         - INCREASE_LIQUIDITY: abi.encode(uint256 tokenId, uint256 liquidity, uint128 amount0Max,
///                                          uint128 amount1Max, bytes hookData)
///         - DECREASE_LIQUIDITY: abi.encode(uint256 tokenId, uint256 liquidity, uint128 amount0Min,
///                                          uint128 amount1Min, bytes hookData)
///         - MINT_POSITION:      abi.encode(PoolKey, int24 tickLower, int24 tickUpper, uint256 liquidity,
///                                          uint128 amount0Max, uint128 amount1Max, address owner, bytes hookData)
///         - BURN_POSITION:      abi.encode(uint256 tokenId, uint128 amount0Min, uint128 amount1Min, bytes hookData)
///         - SETTLE_PAIR:        abi.encode(address currency0, address currency1) — pays the full debt of both
///                               currencies from the caller via Permit2
///         - TAKE_PAIR:          abi.encode(address currency0, address currency1, address recipient) — takes the
///                               full credit of both currencies
/// @dev In v4 every liquidity modification also settles the position's accrued fees into the caller's delta
///      (there is no `tokensOwed`): DECREASE_LIQUIDITY with liquidity = 0 + TAKE_PAIR = collect fees only.
library V4Actions {
    uint8 internal constant INCREASE_LIQUIDITY = 0x00;
    uint8 internal constant DECREASE_LIQUIDITY = 0x01;
    uint8 internal constant MINT_POSITION = 0x02;
    uint8 internal constant BURN_POSITION = 0x03;
    uint8 internal constant SETTLE_PAIR = 0x0d;
    uint8 internal constant TAKE_PAIR = 0x11;
}

src/adapters/uniswap/v4/V4StateReader.so.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {IPoolManagerMinimal} from "contracts/adapters/uniswap/v4/IPoolManagerMinimal.sol";

/// @notice Reads Uniswap v4 pool state straight out of the PoolManager's storage via `extsload` — the v4
///         PoolManager exposes no per-pool getters. Layout (pools mapping at slot 6, derived empirically on RHC —
///         notes/RHC_ADDRESSES.md):
///           state      = keccak256(abi.encodePacked(poolId, uint256(6)))
///           state + 0  = slot0            sqrtPriceX96 (160) | tick (24) | protocolFee (24) | lpFee (24)
///           state + 1  = feeGrowthGlobal0X128
///           state + 2  = feeGrowthGlobal1X128
///           state + 3  = liquidity
///           state + 4  = mapping(int24 => TickInfo)   {uint128 liquidityGross | int128 liquidityNet;
///                                                       feeGrowthOutside0X128; feeGrowthOutside1X128}
///           state + 6  = mapping(bytes32 => Position) {uint128 liquidity; feeGrowthInside0LastX128;
///                                                       feeGrowthInside1LastX128}
///         Cross-checked on the RHC fork: the fees this reader predicts equal what the PositionManager pays out.
/// @dev Written from the storage layout — no v4-core source is vendored.
library V4StateReader {
    uint256 internal constant POOLS_SLOT = 6;
    uint256 internal constant FEE_GROWTH_GLOBAL0_OFFSET = 1;
    uint256 internal constant TICKS_OFFSET = 4;
    uint256 internal constant POSITIONS_OFFSET = 6;

    /// @dev The pool's spot price and current tick. sqrtPriceX96 == 0 ⇔ the pool is not initialized.
    function getSlot0(IPoolManagerMinimal manager, bytes32 poolId)
        internal
        view
        returns (uint160 sqrtPriceX96, int24 tick)
    {
        uint256 data = uint256(manager.extsload(_stateSlot(poolId)));
        sqrtPriceX96 = uint160(data);
        tick = int24(uint24(data >> 160));
    }

    function getFeeGrowthGlobals(IPoolManagerMinimal manager, bytes32 poolId)
        internal
        view
        returns (uint256 feeGrowthGlobal0X128, uint256 feeGrowthGlobal1X128)
    {
        bytes32[] memory data = manager.extsload(bytes32(uint256(_stateSlot(poolId)) + FEE_GROWTH_GLOBAL0_OFFSET), 2);
        feeGrowthGlobal0X128 = uint256(data[0]);
        feeGrowthGlobal1X128 = uint256(data[1]);
    }

    function getTickFeeGrowthOutside(IPoolManagerMinimal manager, bytes32 poolId, int24 tick)
        internal
        view
        returns (uint256 feeGrowthOutside0X128, uint256 feeGrowthOutside1X128)
    {
        bytes32 ticksMapping = bytes32(uint256(_stateSlot(poolId)) + TICKS_OFFSET);
        bytes32 slot = keccak256(abi.encodePacked(int256(tick), ticksMapping));
        bytes32[] memory data = manager.extsload(bytes32(uint256(slot) + 1), 2);
        feeGrowthOutside0X128 = uint256(data[0]);
        feeGrowthOutside1X128 = uint256(data[1]);
    }

    /// @dev `posKey` = {positionKey}(owner, tickLower, tickUpper, salt); for PositionManager positions the owner is
    ///      the PositionManager and salt = bytes32(tokenId).
    function getPositionState(IPoolManagerMinimal manager, bytes32 poolId, bytes32 posKey)
        internal
        view
        returns (uint128 liquidity, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128)
    {
        bytes32 positionsMapping = bytes32(uint256(_stateSlot(poolId)) + POSITIONS_OFFSET);
        bytes32 slot = keccak256(abi.encodePacked(posKey, positionsMapping));
        bytes32[] memory data = manager.extsload(slot, 3);
        liquidity = uint128(uint256(data[0]));
        feeGrowthInside0LastX128 = uint256(data[1]);
        feeGrowthInside1LastX128 = uint256(data[2]);
    }

    function positionKey(address owner, int24 tickLower, int24 tickUpper, bytes32 salt)
        internal
        pure
        returns (bytes32 key)
    {
        key = keccak256(abi.encodePacked(owner, tickLower, tickUpper, salt));
    }

    function _stateSlot(bytes32 poolId) private pure returns (bytes32 slot) {
        slot = keccak256(abi.encodePacked(poolId, POOLS_SLOT));
    }
}

src/interfaces/IAdapterFees.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

/**
 * @title IAdapterFees
 * @notice OPTIONAL fees view of a {IPositionAdapter} (advertised through ERC-165): splits what {position} reports into
 *         its fee part so callers (keepers, the FE, off-chain accounting) can tell principal from fees. Purely
 *         additive — the vault never reads it, capability masks do not cover it, and an adapter without it is still a
 *         complete {IPositionAdapter}. Raw token units only — no USD, no valuation.
 * @custom:security-contact security@mysun.example
 */
interface IAdapterFees {
    /// @notice The GROSS fee part of each position token: fees settled to the adapter but not yet delivered (the v4 fee
    ///         bank / the v3 NFPM `tokensOwed`) + fees accrued in the venue since the position's last modification
    ///         (feeGrowthInside accounting — no price involved). Exactly the sum {IPositionAdapter-position} nets the
    ///         vault's performance fee out of; principal and free idle are NOT included. Never pokes the venue: an
    ///         empty (or zero-liquidity) position reports the settled part only.
    /// @return tokens The adapter's tokens, index-aligned with and in the same (stable) order as `position()`.
    /// @return amounts `amounts[i]` = the gross fee part of `tokens[i]`.
    function fees() external view returns (address[] memory tokens, uint256[] memory amounts);
}

src/interfaces/IDepositSplit.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

/**
 * @title IDepositSplit
 * @notice Stateless split of a deposit's pulled amounts across the CALLER vault's adapters, in proportion to what
 *         each adapter currently reports holding per token (deposit-deploy, T2d). Raw token units only — no USD,
 *         no valuation, no oracle.
 * @custom:security-contact security@mysun.example
 */
interface IDepositSplit {
    /// @dev `required.length != registry.length`.
    error DepositSplit__LengthMismatch();

    /// @notice Per-adapter deploy vectors for `required` (aligned to `registry`), over `msg.sender`'s `adapters()`.
    /// @dev amount_ij = floor(required_r * a_ij / D_r), with a_ij = adapter i's reported `position()` amount of its
    ///      j-th token, r = that token's index in `registry` and D_r = Σ_i a_ir. A token absent from `registry`, or
    ///      one with D_r == 0, gets 0. Σ_ij amount_ij (per token r) <= required_r; the floor dust is not assigned.
    /// @param registry Tokens the amounts are denominated in (the vault passes the deposit's `tokens_`).
    /// @param required Amount per `registry` token to split.
    /// @return flat ONE flat vector of frames, one per adapter in `adapters()` order: `[n_i][amount_i1 .. amount_in]`
    ///         (n_i = the adapter's `position()` token count, amounts in that token order), or the single word `[0]`
    ///         when every amount of adapter i is 0. Each non-empty frame is ABI-shaped like a `uint256[]` in memory.
    function split(address[] calldata registry, uint256[] calldata required)
        external
        view
        returns (uint256[] memory flat);
}

src/interfaces/ILiquidityAdapter.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

/**
 * @title ILiquidityAdapter
 * @notice Precise-liquidity capability of a concentrated-liquidity {IPositionAdapter} (strategy layer P1,
 *         `notes/EXECUTION-PLANS.md`). The keeper sizes the operation (exact raw liquidity, absolute bounds, pull
 *         caps, swap floor); the adapter enforces the owner's range constraints and the venue guards. Every
 *         destination is hard-wired to the vault — no parameter can route funds anywhere else.
 *
 *         Token order is the adapter's `position()` order (`[token0, token1]`, pool order). Raw liquidity is the
 *         venue's own unit. No USD, no valuation.
 * @custom:security-contact security@mysun.example
 */
interface ILiquidityAdapter {
    struct AddLiquidityParams {
        int24 tickLower; // absolute, spacing-aligned, inside the adapter's constraints
        int24 tickUpper;
        uint128 liquidity; // raw target liquidity
        uint128 minLiquidity; // acceptable-actual floor (caps may bind actual below target)
        uint256 maxAmount0; // pull caps from the vault — approved, never exceeded
        uint256 maxAmount1;
        uint256 minSwapOut; // explicit floor on the internal ratio swap (stricter-of wins)
    }

    struct RemoveLiquidityParams {
        uint128 liquidity; // exact raw liquidity; 0 = idle-refund mode ONLY
        uint256 minPrincipal0; // floors apply to PRINCIPAL only — idle must never satisfy them
        uint256 minPrincipal1;
    }

    /// @notice Add up to `p.liquidity` to the position at `[p.tickLower, p.tickUpper]` (fresh mint, or increase of
    ///         the live position with the SAME bounds), pulling at most `p.maxAmount0/1` from the vault, and refund
    ///         the operation's unused amounts to the vault.
    /// @return tokenId Position id (new on a fresh mint).
    /// @return liquidityAdded Raw liquidity actually added (>= `p.minLiquidity`).
    /// @return amount0Spent Token0 added into the position.
    /// @return amount1Spent Token1 added into the position.
    /// @return amount0Refunded Token0 returned to the vault (this operation's leftover only).
    /// @return amount1Refunded Token1 returned to the vault (this operation's leftover only).
    function addLiquidity(AddLiquidityParams calldata p)
        external
        returns (
            uint256 tokenId,
            uint128 liquidityAdded,
            uint256 amount0Spent,
            uint256 amount1Spent,
            uint256 amount0Refunded,
            uint256 amount1Refunded
        );

    /// @notice `p.liquidity > 0`: remove exactly that raw liquidity, enforce the principal floors, collect the
    ///         position's fees, everything to the vault, position kept. `p.liquidity == 0`: refund the adapter's
    ///         free idle to the vault and touch nothing else.
    /// @return principal0 Token0 principal released by the removal.
    /// @return principal1 Token1 principal released by the removal.
    /// @return fees0 Token0 fees collected alongside.
    /// @return fees1 Token1 fees collected alongside.
    /// @return idleRefunded0 Token0 idle refunded (idle-refund mode only; 0 otherwise).
    /// @return idleRefunded1 Token1 idle refunded (idle-refund mode only; 0 otherwise).
    function removeLiquidity(RemoveLiquidityParams calldata p)
        external
        returns (
            uint256 principal0,
            uint256 principal1,
            uint256 fees0,
            uint256 fees1,
            uint256 idleRefunded0,
            uint256 idleRefunded1
        );

    /// @notice Live position id (0 = none). Read by the vault to tag its {removeLiquidity} event.
    /// @dev Not in the P1 shape proposal — added because the vault's `LiquidityRemoved` event carries the id and
    ///      `removeLiquidity` does not return it (see REPORT-EXECPLAN-P1.md).
    function tokenId() external view returns (uint256);

    /// @notice The owner's range constraints in one call, for keepers/planners sizing an {addLiquidity}: every range
    ///         must satisfy `minTick <= tickLower < tickUpper <= maxTick` and
    ///         `minRangeTicks <= tickUpper - tickLower <= maxRangeTicks` (bounds aligned to the venue's tick spacing).
    function rangeConstraints()
        external
        view
        returns (int24 minTick, int24 maxTick, int24 minRangeTicks, int24 maxRangeTicks);

    /// @notice The plan pin (strategy layer P3): the live position and the owner-config version in one call. With no
    ///         position the four position fields are 0; `configVersion` (starts at 1) is always the live counter and
    ///         moves on EVERY owner config change of the adapter — a plan pinned before such a change goes stale.
    function positionState()
        external
        view
        returns (uint256 tokenId, int24 tickLower, int24 tickUpper, uint128 liquidity, uint32 configVersion);
}

