// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.34;

import {Vm} from "forge-std/Vm.sol";

/// @notice Recorded-log readers shared by the fork suites: the on-chain evidence that a UniversalRouter swap
///         reached the intended live venue, and the allowance trail it left.
library ForkLogs {
    bytes32 internal constant ERC20_TRANSFER = keccak256("Transfer(address,address,uint256)");
    bytes32 internal constant ERC20_APPROVAL = keccak256("Approval(address,address,uint256)");
    /// @dev Permit2 IAllowanceTransfer.Approval(owner, token, spender, amount, expiration) — owner/token/spender indexed.
    bytes32 internal constant PERMIT2_APPROVAL = keccak256("Approval(address,address,address,uint160,uint48)");
    /// @dev v3-core IUniswapV3PoolEvents.Swap — sender/recipient indexed; amounts from the POOL's perspective.
    bytes32 internal constant V3_SWAP = keccak256("Swap(address,address,int256,int256,uint160,uint128,int24)");
    /// @dev v4-core IPoolManager.Swap — id/sender indexed; amounts from the SWAPPER's perspective (negative = paid).
    bytes32 internal constant V4_SWAP = keccak256("Swap(bytes32,address,int128,int128,uint160,uint128,int24,uint24)");

    struct V3Swap {
        address sender;
        address recipient;
        int256 amount0;
        int256 amount1;
    }

    struct V4Swap {
        address sender;
        int128 amount0;
        int128 amount1;
    }

    /// @dev Every v3 `Swap` emitted by `pool`, in order.
    function v3Swaps(Vm.Log[] memory logs, address pool) internal pure returns (V3Swap[] memory swaps) {
        swaps = new V3Swap[](logs.length);
        uint256 n;
        for (uint256 i; i < logs.length; ++i) {
            Vm.Log memory l = logs[i];
            if (l.emitter == pool && l.topics.length == 3 && l.topics[0] == V3_SWAP) {
                (int256 amount0, int256 amount1,,,) = abi.decode(l.data, (int256, int256, uint160, uint128, int24));
                swaps[n++] = V3Swap(_addr(l.topics[1]), _addr(l.topics[2]), amount0, amount1);
            }
        }
        assembly ("memory-safe") {
            mstore(swaps, n)
        }
    }

    /// @dev Every v4 `Swap` the PoolManager `manager` emitted for `poolId`, in order.
    function v4Swaps(Vm.Log[] memory logs, address manager, bytes32 poolId)
        internal
        pure
        returns (V4Swap[] memory swaps)
    {
        swaps = new V4Swap[](logs.length);
        uint256 n;
        for (uint256 i; i < logs.length; ++i) {
            Vm.Log memory l = logs[i];
            if (l.emitter == manager && l.topics.length == 3 && l.topics[0] == V4_SWAP && l.topics[1] == poolId) {
                (int128 amount0, int128 amount1,,,,) =
                    abi.decode(l.data, (int128, int128, uint160, uint128, int24, uint24));
                swaps[n++] = V4Swap(_addr(l.topics[2]), amount0, amount1);
            }
        }
        assembly ("memory-safe") {
            mstore(swaps, n)
        }
    }

    /// @dev The sequence of ERC-20 `Transfer(from, to)` amounts of `token`.
    function transfers(Vm.Log[] memory logs, address token, address from, address to)
        internal
        pure
        returns (uint256[] memory amounts)
    {
        amounts = new uint256[](logs.length);
        uint256 n;
        for (uint256 i; i < logs.length; ++i) {
            Vm.Log memory l = logs[i];
            if (
                l.emitter == token && l.topics.length == 3 && l.topics[0] == ERC20_TRANSFER
                    && _addr(l.topics[1]) == from && _addr(l.topics[2]) == to
            ) {
                amounts[n++] = abi.decode(l.data, (uint256));
            }
        }
        assembly ("memory-safe") {
            mstore(amounts, n)
        }
    }

    /// @dev The sequence of ERC-20 `Approval(owner, spender)` values `token` emitted.
    function erc20Approvals(Vm.Log[] memory logs, address token, address owner, address spender)
        internal
        pure
        returns (uint256[] memory values)
    {
        values = new uint256[](logs.length);
        uint256 n;
        for (uint256 i; i < logs.length; ++i) {
            Vm.Log memory l = logs[i];
            if (
                l.emitter == token && l.topics.length == 3 && l.topics[0] == ERC20_APPROVAL
                    && _addr(l.topics[1]) == owner && _addr(l.topics[2]) == spender
            ) {
                values[n++] = abi.decode(l.data, (uint256));
            }
        }
        assembly ("memory-safe") {
            mstore(values, n)
        }
    }

    /// @dev The sequence of Permit2 allowance amounts `owner` granted `spender` on `token`, and the first expiration.
    function permit2Approvals(Vm.Log[] memory logs, address permit2, address token, address owner, address spender)
        internal
        pure
        returns (uint256[] memory amounts, uint256 firstExpiration)
    {
        amounts = new uint256[](logs.length);
        uint256 n;
        for (uint256 i; i < logs.length; ++i) {
            Vm.Log memory l = logs[i];
            if (
                l.emitter == permit2 && l.topics.length == 4 && l.topics[0] == PERMIT2_APPROVAL
                    && _addr(l.topics[1]) == owner && _addr(l.topics[2]) == token && _addr(l.topics[3]) == spender
            ) {
                (uint160 amount, uint48 expiration) = abi.decode(l.data, (uint160, uint48));
                if (n == 0) {
                    firstExpiration = expiration;
                }
                amounts[n++] = amount;
            }
        }
        assembly ("memory-safe") {
            mstore(amounts, n)
        }
    }

    function _addr(bytes32 topic) private pure returns (address) {
        return address(uint160(uint256(topic)));
    }
}

